window.__BUNDLE = {"body": "<div class=\"wrap\">\n\n  <section id=\"intro\" class=\"stack\" style=\"gap:28px\">\n    <div data-greeting></div>\n    <div id=\"testStart\" class=\"stack\" style=\"gap:28px\" hidden>\n      <div class=\"stack\">\n        <div class=\"eyebrow\">Самотест для себя · 10 минут</div>\n        <h1>Компас адаптации</h1>\n        <p class=\"lead\">Переезд в новую страну меняет всё: язык, быт, работу, круг общения и даже то, как ты видишь себя. Этот тест поможет понять, где ты сейчас на пути адаптации, что уже стало опорой и куда сделать следующий шаг.</p>\n      </div>\n      <div class=\"st-resume\" id=\"kResume\" hidden></div>\n      <div id=\"kAB\"></div>\n      <div class=\"roles k-roles\">\n        <div class=\"role ka0\"><b>Язык</b><span>и общение</span></div>\n        <div class=\"role ka1\"><b>Быт</b><span>и система</span></div>\n        <div class=\"role ka2\"><b>Дело</b><span>и реализация</span></div>\n        <div class=\"role ka3\"><b>Люди</b><span>и связи</span></div>\n        <div class=\"role ka4\"><b>Ресурс</b><span>тело и отдых</span></div>\n        <div class=\"role ka5\"><b>Я</b><span>и смысл</span></div>\n      </div>\n      <div data-reportfan></div>\n      <div class=\"card stack\">\n        <h3>Как это устроено</h3>\n        <p>Здесь почти нет вопросов про чувства, только про то, что ты делаешь. Вспомни последние 4 недели и отмечай, как часто это было на самом деле. Правильных ответов нет, есть только твоя картина сейчас.</p>\n        <p>Сначала два коротких вопроса о твоём переезде, потом шесть сфер новой жизни и небольшой блок о двух культурах: твоей и новой. В конце ты получишь подробный разбор с картинками, рекомендациями и вопросами для размышления. Разбор можно получить в PDF.</p>\n        <div class=\"scale-legend\"><span><b>0</b> ни разу</span><span><b>1</b> 1–2 раза</span><span><b>2</b> время от времени</span><span><b>3</b> часто</span><span><b>4</b> почти всегда</span></div>\n      </div>\n      <div data-testinfo></div>\n      <div class=\"stack\">\n        <h3>Как тебя зовут?</h3>\n        <div class=\"row\" style=\"align-items:stretch\">\n          <div class=\"field\"><label for=\"nameMe\">Твоё имя</label><input id=\"nameMe\" maxlength=\"30\" autocomplete=\"given-name\" placeholder=\"Например, Анна\"></div>\n        </div>\n        <p class=\"note\">Имя нужно только для красивого разбора.</p>\n      </div>\n      <div><button class=\"btn\" id=\"startBtn\">Начать тест</button></div>\n      <div data-share=\"compact\" style=\"margin-top:8px\"></div>\n    </div>\n  </section>\n\n  <section id=\"quiz\" class=\"stack\" hidden style=\"gap:20px\">\n    <div class=\"stack\" style=\"gap:10px\">\n      <div class=\"row\" style=\"justify-content:space-between\">\n        <span class=\"eyebrow\" id=\"stepLabel\"></span>\n        <span class=\"eyebrow\" id=\"countLabel\"></span>\n      </div>\n      <div class=\"progress\"><i id=\"prog\" style=\"width:0\"></i></div>\n    </div>\n    <div class=\"stack\" style=\"gap:6px\">\n      <div><span class=\"part-tag\" id=\"partTag\"></span></div>\n      <h2 id=\"roleTitle\"></h2>\n      <p class=\"muted\" id=\"roleSub\"></p>\n    </div>\n    <div class=\"card\" id=\"qlist\" style=\"padding-block:6px\"></div>\n    <div class=\"row\" style=\"justify-content:space-between\">\n      <button class=\"btn ghost\" id=\"back\">Назад</button>\n      <button class=\"btn\" id=\"next\" disabled>Дальше</button>\n    </div>\n  </section>\n\n  <section id=\"result\" hidden>\n    <div class=\"rep\" id=\"report\"></div>\n    <div data-share style=\"margin-top:18px\"></div>\n    <div data-lead></div>\n  </section>\n\n  <div data-disclaimer style=\"margin-top:28px\"></div>\n</div>\n<div class=\"pdf-stage\" id=\"stage\" aria-hidden=\"true\"></div>\n", "scripts": ["/* Настройки сайта, общие для всех тестов */\n// Ссылка веб-приложения Google Apps Script (заканчивается на /exec). Одна на все тесты.\nconst ENDPOINT = 'https://script.google.com/macros/s/AKfycbyizp1XjzNdrUj4WHgj4Vyj81QhjY2D7puqyeY3LaweWB4mePxPhfHCx5fIsfaJy9hV/exec';\n// Адрес сайта после размещения, например 'https://irina-tests.netlify.app/' (нужен для ссылок в PDF)\nconst SITE_URL = 'https://irynawiederkehr-cmd.github.io/tests/';\n// Ссылки на тесты, пока сайт не размещён (используются для кнопки «Поделиться» и блока «Пройди также»).\n// После размещения сайта достаточно заполнить SITE_URL — эти ссылки больше не понадобятся.\nconst TEST_LINKS = {\n  'roza-lyubvi': 'https://claude.ai/artifact/6Nv7pCtqpAd9xoWUkvEwS1',\n  'kompas': 'https://claude.ai/artifact/5TPCgkiVSZEr8H2g8d1UkY'\n};\n", "const BRAND = 'coach';\nconst TEST_META = { id: 'kompas', name: 'Компас адаптации' };\nconst TEST_INFO = {\n  why: 'Я разработала этот опросник, чтобы помочь тебе бережно посмотреть на свою жизнь в новой стране. В эмиграции легко видеть только то, что пока не получается. Опросник показывает и трудности, и опоры, которые у тебя уже есть, и помогает выбрать следующий шаг, а не пытаться изменить всё сразу.',\n  from: [\n    'Ты живёшь в новой стране, и столько всего нужно одновременно: язык, документы, работа, новые люди, дети, ты сама. Кажется, что везде немного получается и везде немного не хватает.',\n    'Трудно понять, где ты на самом деле: всё ли идёт как надо, или ты застряла, и за что браться в первую очередь.'\n  ],\n  to: [\n    'Ты видишь шесть сфер своей новой жизни и знаешь, какие уже стали опорой, а какие пока звучат тихо.',\n    'Понимаешь, как ты держишь связь со своей культурой и с новой, на каком этапе адаптации находишься и что на нём особенно помогает. Видишь, куда тебе хочется и насколько далеко это от того, что есть.',\n    'И уходишь с планом маленьких шагов на четыре недели.'\n  ],\n  key: 'Адаптация идёт не по прямой, а волнами, и у каждого свой темп. Не нужно подтягивать всё сразу: одна сфера, укреплённая по-настоящему, помогает остальным.',\n  gives: [\n    'Ты увидишь, какие из шести сфер новой жизни уже стали опорой, а какие пока звучат тихо.',\n    'Поймёшь, как ты сейчас держишь связь со своей культурой и с новой.',\n    'Узнаешь, на каком этапе адаптации находишься, и что на нём особенно помогает.',\n    'Получишь план маленьких шагов на 4 недели и вопросы для размышления.'\n  ],\n  next: [\n    'Отнесись к результату бережно: это снимок последних 4 недель, а не оценка тебя.',\n    'Начни с одной сферы и одного маленького шага, а не со всего сразу.',\n    'Опирайся на то, что уже работает: сильные сферы помогают подтянуть остальные.',\n    'Через 4 недели пройди тест снова и посмотри, что изменилось.',\n    'Если становится очень тяжело, поговори с близким человеком или со специалистом.'\n  ]\n};\nconst TEST_DISCLAIMER = ['Этот опросник — инструмент самопознания. Он не является психологической или медицинской диагностикой, психотерапевтическим заключением и не заменяет консультацию специалиста.', null, null];\n\n/* превью отчёта веером на стартовой странице (картинки — src/kompas/preview/1..5.jpg) */\nconst REPORT_FAN = {\n \"pages\": \"10\",\n \"title\": \"Каким будет твой разбор\",\n \"lead\": \"Личный разбор на 10 страницах соберётся из твоих ответов и останется у тебя в PDF. Вот несколько страниц из примера: так выглядит разбор Анны.\",\n \"items\": [\n  {\n   \"t\": \"Мост между мирами\",\n   \"d\": \"Как ты сейчас держишь две культуры, свою и новую, и на что можешь опереться.\"\n  },\n  {\n   \"t\": \"Три колеса жизни\",\n   \"d\": \"Шесть сфер: где ты сейчас и куда хочется. Разница подсказывает, куда направить силы.\"\n  },\n  {\n   \"t\": \"Шесть сфер подробно\",\n   \"d\": \"Язык, быт, дело, люди, ресурс и смысл: что уже держит и что поможет каждой сфере.\"\n  },\n  {\n   \"t\": \"Что останавливает\",\n   \"d\": \"Хочешь ли ты остаться, что тормозит движение и твои собственные слова о цели.\"\n  },\n  {\n   \"t\": \"Время опор\",\n   \"d\": \"Твой этап адаптации на пути, который проходят почти все, кто переехал.\"\n  }\n ]\n};\n", "/* язык страницы: задаёт загрузчик (ru, uk, de, en) */\nconst DATE_LOCALE = ({ ru:'ru-RU', uk:'uk-UA', de:'de-CH', en:'en-GB' })[(typeof LANG !== 'undefined') ? LANG : 'ru'] || 'ru-RU';\n/* =====================================================================\n   Общие тексты и блоки для всех тестов Ирины Вознесенской.\n   Меняешь здесь — меняется во всех тестах сразу.\n   ===================================================================== */\n\n/* ---------- Обо мне и контакты ---------- */\nconst AUTHOR = {\n  name: 'Ирина Вознесенская',\n  about: 'Коуч ICF в Швейцарии и психолог в Украине.',\n  coach: { place: 'Швейцария · Цюрих', title: 'Коуч', text: 'Трансформационный коуч и нейрокоуч, ICF. Работаю на глубине, через эмоциональный интеллект: с тем, что лежит под привычными реакциями и решениями. Поэтому трансформация происходит на глубинном уровне и остаётся с человеком надолго. Помогаю русскоязычным людям, которые переехали, пройти адаптацию: найти себя и своё место в новом мире. В Швейцарии работаю только как коуч. Коучинг не является психотерапией и не заменяет психологическую или медицинскую помощь.',\n           instagram: 'https://www.instagram.com/iryna.voznesenskaya/', telegram: 'https://t.me/IrynaNeuroCoach_channel' },\n  psy:   { place: 'Украина · Киев', title: 'Психолог в Украине', text: 'Работаю на глубине бессознательных процессов: через глубокий диалог, метафору, образы и символы, опираясь на аналитическую психологию Карла Юнга. Помогаю парам услышать друг друга, вернуть близость и найти баланс. Как психолог работаю только с клиентами в Украине, на основании украинской квалификации.',\n           instagram: 'https://www.instagram.com/voznesenskayairyna.psy/', telegram: 'https://t.me/IrynaVoznesenska_psy' }\n};\n\n/* ---------- Все тесты (для главной и блока «Пройди также») ---------- */\nconst TESTS = [\n  { id: 'kompas', path: 'kompas/', name: 'Компас адаптации', brand: 'coach', tag: 'Для себя · 10 минут', pages: 10,\n    door: 'Я переехала и хочу понять, где я сейчас',\n    text: 'Где ты сейчас после переезда: шесть сфер новой жизни, твой путь между двумя культурами и следующий маленький шаг.' },\n  { id: 'stupeni', path: 'stupeni/', name: 'Восемь ступеней к дому', brand: 'coach', tag: 'Для себя · путеводитель и тест · 20 минут', pages: 11,\n    door: 'Хочу понять, почему не получается двигаться к цели',\n    text: 'Жизнь в новой стране строится как дом, снизу вверх. Узнай, какие из семи ступеней уже держат тебя, а какая поскрипывает, и с чего начать именно тебе.' },\n  { id: 'roza-lyubvi', path: 'roza-lyubvi/', name: 'Роза любви', brand: 'psy', tag: 'Для пары · 15 минут', pages: 11,\n    door: 'Хочу понять, что происходит в нашей паре',\n    text: 'Три роли в паре: притяжение, близость и ответственность. Узнай, какие роли звучат ярко, а какие стали тише, и как вы встречаетесь друг с другом.' }\n];\n\nconst handle = url => '@' + url.replace(/\\/+$/, '').split('/').pop();\nconst pickOne = arr => arr[Math.floor(Math.random() * arr.length)];\nconst BASE = (typeof SITE_BASE !== 'undefined') ? SITE_BASE : '../';\n\nfunction practiceHtml(key){\n  const p = AUTHOR[key];\n  const links = [\n    p.instagram ? `<a href=\"${p.instagram}\" target=\"_blank\" rel=\"noopener\">Instagram ${handle(p.instagram)}</a>` : '',\n    p.telegram ? `<a href=\"${p.telegram}\" target=\"_blank\" rel=\"noopener\">Telegram-канал</a>` : ''\n  ].filter(Boolean).join('');\n  return `<div class=\"practice ${key}\"><span class=\"place\">${p.place}</span><h4>${p.title}</h4><p>${p.text}</p><div class=\"links\">${links}</div></div>`;\n}\nfunction authorHtml(label = 'Об авторе теста'){\n  const order = BRAND === 'coach' ? ['coach','psy'] : ['psy','coach'];\n  return `<div class=\"blk author\"><div class=\"eyebrow\">${label}</div>\n    <div class=\"who\"><div class=\"mono\">ИВ</div><div><b>${AUTHOR.name}</b><span>${AUTHOR.about}</span></div></div>\n    <div class=\"practices\">${order.map(practiceHtml).join('')}</div></div>`;\n}\nfunction footerLine(){\n  return '© ' + new Date().getFullYear() + ' · ' + (typeof TEST_META !== 'undefined' ? '«' + TEST_META.name + '» · ' : '') + (BRAND === 'coach' ? 'Ирина Вознесенская · коуч ICF (Швейцария) · психолог (Украина)' : 'Ирина Вознесенская · психолог (Украина) · коуч ICF (Швейцария)');\n}\n\n/* ---------- Приветствие и обязательный мини-опрос ---------- */\nconst SURVEY = {\n  heard: { q: 'Откуда ты обо мне знаешь?', opts: ['Instagram','Telegram','Рекомендация друзей или знакомых','Поиск в Google','Facebook','Другое'] },\n  interest: { q: 'Что тебе интересно?', opts: ['Психология: отношения в паре','Коучинг: адаптация в эмиграции и поиск себя','Пока просто интересно'] }\n};\nconst GREET = {\n  head: ['Привет! Я {A}','Рада тебе! Меня зовут {A}','Добро пожаловать! Я {A}','Здравствуй! Я {A}'],\n  about: ['Коуч ICF в Швейцарии и психолог в Украине.','Работаю на две страны: коуч ICF в Швейцарии и психолог в Украине.','Помогаю людям находить себя и строить тёплые отношения: как коуч ICF в Швейцарии и как психолог в Украине.'],\n  ask: ['Перед тестом ответь, пожалуйста, на два коротких вопроса. Так я лучше пойму, чем могу быть тебе полезна.',\n        'Два коротких вопроса перед началом, и сразу переходим к тесту.',\n        'Мне важно знать, кто приходит на мои тесты. Ответь, пожалуйста, на два коротких вопроса.']\n};\nfunction greetingHtml(){\n  const order = BRAND === 'coach' ? ['coach','psy'] : ['psy','coach'];\n  const group = key => `<fieldset class=\"survey\"><legend>${SURVEY[key].q} *</legend>${SURVEY[key].opts.map((o, i) =>\n    `<label class=\"check\"><input type=\"checkbox\" id=\"sv-${key}-${i}\" data-sv=\"${key}\" value=\"${o}\"> <span>${o}</span></label>`).join('')}</fieldset>`;\n  return `<div class=\"blk author greet\">\n    <div class=\"who\"><div class=\"mono\">ИВ</div><div><b>${pickOne(GREET.head).replace('{A}', AUTHOR.name)}</b><span>${pickOne(GREET.about)}</span></div></div>\n    <div class=\"practices\">${order.map(practiceHtml).join('')}</div>\n    <div class=\"stack\" style=\"gap:10px\"><p class=\"note\">${pickOne(GREET.ask)} Можно отметить несколько вариантов.</p>\n      <div class=\"surveys\">${group('heard')}${group('interest')}</div>\n      <p class=\"err\" id=\"svErr\" hidden></p>\n      <div><button class=\"btn\" type=\"button\" id=\"svGo\">Перейти к тестированию</button></div></div></div>`;\n}\nfunction surveyAnswers(){\n  const pick = key => [...document.querySelectorAll(`input[data-sv=\"${key}\"]:checked`)].map(i => i.value);\n  return { heard: pick('heard'), interest: pick('interest') };\n}\n\n/* ---------- Живое приглашение в работу (тексты каждый раз собираются заново) ---------- */\nconst INVITES = {\n  psy: {\n    open: ['{N}, спасибо за честные ответы.',\n           '{N}, ты уже делаешь важный шаг: честно смотришь на свою пару.',\n           '{N}, этот разбор — только начало разговора.',\n           '{N}, тест показывает картину, а настоящие изменения начинаются в разговоре.',\n           '{N}, за каждой цифрой в этом разборе стоит твоя история.'],\n    body: ['Цифры показывают, где в паре стало тихо. Но за ними всегда есть что-то своё: усталость, обиды, привычки, непроговорённые ожидания. На встрече мы бережно разберём твою ситуацию и найдём первые шаги, чтобы {F}.',\n           'Иногда достаточно одного точного вопроса, чтобы пара снова услышала друг друга. Если тебе хочется {F}, приглашаю на встречу: спокойно, бережно, без оценок.',\n           'Отношения меняются не от знаний, а от новых действий. Я помогаю парам найти эти действия и не бросить их через неделю. Давай вместе посмотрим, как {F}.',\n           'К изменениям можно идти в одиночку, а можно с поддержкой. На встрече мы обсудим твой треугольник и наметим, как {F}.',\n           'Многие пары годами живут с одним и тем же напряжением, потому что не знают, с чего начать разговор. Я помогу начать его так, чтобы {F}.'],\n    cta:  ['Запишись на встречу-знакомство 30 минут онлайн. Мы познакомимся, проговорим твой запрос и поймём, насколько я могу быть тебе полезна.',\n           'Встреча-знакомство длится 30 минут. Ты рассказываешь, что происходит в паре, я слушаю и задаю вопросы. За это время мы проговорим твой запрос и поймём, насколько я могу быть полезна вам.',\n           'Первая встреча — 30 минут онлайн, чтобы познакомиться, проговорить твой запрос и понять, насколько я могу быть тебе полезна.'],\n    title: ['Приглашаю на встречу 30 минут','Давай поговорим о твоей паре','Следующий шаг — разговор'],\n    legal: 'Консультации психолога проводятся онлайн для клиентов в Украине.'\n  },\n  coach: {\n    open: ['{N}, спасибо, что находишь время на себя.',\n           '{N}, ты уже делаешь важный шаг: смотришь на себя честно и бережно.',\n           '{N}, этот разбор — только начало пути.',\n           '{N}, иногда один тест открывает больше вопросов, чем ответов. И это хорошо.',\n           '{N}, всё, что ты сейчас видишь, можно превратить в опору.'],\n    body: ['Эмиграция меняет всё: язык, привычки, роли в семье и даже то, как мы видим себя. В коучинге мы ищем твои опоры в новом мире и шаг за шагом помогаем тебе {F}.',\n           'Когда меняется страна, меняемся и мы. Иногда это ощущается как потеря себя. Я помогаю найти себя заново, чтобы {F}.',\n           'За твоими плечами уже большой путь. Коучинг помогает собрать этот опыт в силу и {F}.',\n           'Ответы уже есть внутри тебя, но их трудно услышать в суете новой жизни. В работе со мной ты найдёшь свои ответы и решишь, как {F}.',\n           'Адаптация — это не только документы и язык. Это поиск своего места. Давай вместе посмотрим, как {F}.'],\n    cta:  ['Запишись на встречу-знакомство 30 минут онлайн. Мы познакомимся, проговорим твой запрос и поймём, насколько я могу быть тебе полезна.',\n           'Встреча-знакомство длится 30 минут. Ты рассказываешь, что для тебя сейчас важно, я слушаю и задаю вопросы. За это время мы проговорим твой запрос и поймём, насколько я могу быть тебе полезна.',\n           'Первая встреча — 30 минут онлайн, чтобы познакомиться, проговорить твой запрос и понять, насколько я могу быть тебе полезна.'],\n    title: ['Приглашаю на встречу 30 минут','Давай поговорим о тебе','Следующий шаг — разговор'],\n    legal: 'Коучинг не является психотерапией и не заменяет психологическую или медицинскую помощь.'\n  }\n};\nconst INVITE_HUMAN = {\n  coach: 'Тест даёт карту, но не видит тебя целиком. На личной встрече, когда мы работаем с твоим собственным запросом и под твою задачу, работа становится гораздо продуктивнее и даёт ощутимые результаты. Машина не может увидеть то, что заметит живой человек с профессиональными навыками: паузу перед ответом, интонацию, то, о чём ты молчишь, и то, что тебе на самом деле важно. Я работаю на глубине, через эмоциональный интеллект: мы смотрим не только на то, что ты делаешь, но и на то, что ты чувствуешь и что тобой движет. Поэтому изменения происходят на глубинном уровне, а не остаются красивым планом на бумаге.',\n  psy: 'Тест даёт карту, но не видит вашу пару целиком. На личной встрече, когда мы работаем с вашим собственным запросом и под вашу задачу, работа становится гораздо продуктивнее и даёт ощутимые результаты. Машина не может увидеть то, что заметит живой человек с профессиональными навыками: паузу перед ответом, интонацию, то, о чём молчат, и то, что на самом деле важно каждому из вас. Я работаю на глубине бессознательных процессов: через глубокий диалог, метафору и образы, опираясь на аналитическую психологию Карла Юнга. Так становится видно то, что движет парой изнутри и о чём словами сказать трудно.'\n};\nconst INVITE_FOCUS_DEFAULT = { psy: 'в отношениях стало больше тепла и понимания', coach: 'найти своё место в новом мире' };\nlet inviteSeed = null;\nfunction resetInvite(){ inviteSeed = null; }\nfunction invitePractice(country){\n  // как психолог Ирина работает только с клиентами в Украине; остальных приглашаем в коучинг\n  if (BRAND === 'psy' && country && country !== 'Украина') return 'coach';\n  return BRAND;\n}\nfunction inviteHtml(ctx){\n  if (!inviteSeed) inviteSeed = Array.from({length:6}, () => Math.random());\n  const key = invitePractice(ctx.country);\n  const P = INVITES[key], A = AUTHOR[key];\n  const pick = (arr, i) => arr[Math.floor(inviteSeed[i] * arr.length)];\n  const N = ctx.name || '';\n  const F = (ctx.focus && ctx.focus[key]) || INVITE_FOCUS_DEFAULT[key];\n  const fill = t => { let s = N ? t.replace('{N}', N) : t.replace('{N}, ', ''); s = s.replace('{F}', F); return s.charAt(0).toUpperCase() + s.slice(1); };\n  const links = [A.telegram ? `<a href=\"${A.telegram}\" target=\"_blank\" rel=\"noopener\">Telegram: ${A.telegram.replace('https://','')}</a>` : '',\n                 A.instagram ? `<a href=\"${A.instagram}\" target=\"_blank\" rel=\"noopener\">Instagram: ${handle(A.instagram)}</a>` : ''].filter(Boolean);\n  const other = key === 'psy' ? 'coach' : 'psy';\n  const wantsOther = (ctx.interest || []).some(x => other === 'coach' ? /Коучинг/.test(x) : /Психология/.test(x));\n  const otherLine = wantsOther && !(other === 'psy' && ctx.country && ctx.country !== 'Украина')\n    ? `<p class=\"note\">Тебе интересно и направление «${AUTHOR[other].title.replace(/^./, c => c.toLowerCase())}». Об этой работе можно узнать здесь: <a href=\"${AUTHOR[other].telegram}\" target=\"_blank\" rel=\"noopener\">${AUTHOR[other].telegram.replace('https://','')}</a></p>` : '';\n  const word = 'ВСТРЕЧА';\n  const ig = A.instagram ? 'https://ig.me/m/' + handle(A.instagram).slice(1) : '';\n  return `<div class=\"blk invite ${key}\">\n    <div class=\"inv-letter\">\n      <div class=\"eyebrow\">${key === 'psy' ? 'Работа над отношениями' : 'Работа над собой'}</div>\n      <h2>${pick(P.title, 0)}</h2>\n      <p class=\"inv-open\">${fill(pick(P.open, 1))}</p>\n      <p>${fill(pick(P.body, 2))}</p>\n      <p class=\"inv-human\">${key === 'psy' ? INVITE_HUMAN.psy : INVITE_HUMAN.coach}</p>\n      <p>${fill(pick(P.cta, 3))}</p>\n      <p class=\"inv-sign\">${AUTHOR.name.split(' ')[0]}</p>\n    </div>\n    <div class=\"inv-ticket\">\n      <div class=\"inv-facts\"><span><b>30</b>минут</span><span><b>онлайн</b>из дома</span><span><b>1:1</b>только мы</span></div>\n      <div class=\"inv-how\">\n        <p>Чтобы записаться, напиши мне одно слово:</p>\n        <div class=\"inv-word\"><span>«${word}»</span><button type=\"button\" class=\"inv-copy\" data-copy=\"${word}\">Скопировать</button></div>\n        <p class=\"inv-small\">и я предложу удобное время.</p>\n      </div>\n      <div class=\"inv-links\">\n        ${ig ? `<a class=\"inv-btn main\" href=\"${ig}\" target=\"_blank\" rel=\"noopener\">Написать в Instagram</a>` : ''}\n        ${A.telegram ? `<a class=\"inv-btn\" href=\"${A.telegram}\" target=\"_blank\" rel=\"noopener\">Telegram</a>` : ''}\n      </div>\n    </div>\n    ${otherLine}\n    <p class=\"note inv-legal\">${P.legal}</p></div>`;\n}\n\ndocument.addEventListener('click', async ev => {\n  const b = ev.target.closest('.inv-copy'); if (!b) return;\n  try { await navigator.clipboard.writeText(b.dataset.copy); b.textContent = 'Скопировано ✓'; }\n  catch(e){ const r = document.createRange(); r.selectNodeContents(b.previousElementSibling); const sel = getSelection(); sel.removeAllRanges(); sel.addRange(r); b.textContent = 'Выделено'; }\n  setTimeout(() => b.textContent = 'Скопировать', 2500);\n});\n\n/* ---------- Колесо-лепестки (общее для всех тестов) ----------\n   fill — закрашенные лепестки (0–100), outline — пунктир второй точки (0–100), sec — [{label, fill, line}] */\nlet __wheelN = 0;\nfunction petalWheelSVG(sec, fill, outline, size, turn){\n  const n = sec.length, a0 = -Math.PI / 2 + (turn || 0) * 2 * Math.PI / n, da = 2 * Math.PI / n;\n  const sideLen = Math.max(0, ...sec.map((q, k) => Math.abs(Math.cos(a0 + (k + .5) * da)) > .3 ? q.label.length : 0));\n  const W = size || 340, c = W / 2, R0 = W / 2 - Math.max(66, 16 + sideLen * 6.8), h = da / 2 * .9, id = 'pw' + (++__wheelN);\n  const P = (r, a) => `${(c + r * Math.cos(a)).toFixed(1)} ${(c + r * Math.sin(a)).toFixed(1)}`;\n  const petal = (r, th) => { r = Math.max(r, 10); const e = h * .8;\n    return `M${c} ${c}C${P(r * .45, th - h * 1.12)} ${P(r * .86, th - h * 1.12)} ${P(r * .97, th - e)}A${r} ${r} 0 0 1 ${P(r * .97, th + e)}C${P(r * .86, th + h * 1.12)} ${P(r * .45, th + h * 1.12)} ${c} ${c}Z`; };\n  let s = `<svg viewBox=\"0 0 ${W} ${W}\" role=\"img\" aria-label=\"Колесо\"><defs><filter id=\"${id}\" x=\"-5%\" y=\"-5%\" width=\"110%\" height=\"110%\"><feTurbulence type=\"fractalNoise\" baseFrequency=\".035\" numOctaves=\"2\" seed=\"${__wheelN % 7 + 2}\"/><feDisplacementMap in=\"SourceGraphic\" scale=\"4\"/></filter></defs>`;\n  s += `<circle cx=\"${c}\" cy=\"${c}\" r=\"${R0 + 6}\" fill=\"#FFFCF8\"/>`;\n  [.25, .5, .75, 1].forEach(f => s += `<circle cx=\"${c}\" cy=\"${c}\" r=\"${(R0 * f).toFixed(1)}\" fill=\"none\" stroke=\"#E2D6C6\" stroke-width=\"${f === 1 ? 1 : .7}\" ${f < 1 ? 'stroke-dasharray=\"1.5 4\"' : ''}/>`);\n  sec.forEach((q, k) => {\n    const th = a0 + (k + .5) * da;\n    if (fill) { const d = petal(R0 * fill[k] / 100, th); s += `<path d=\"${d}\" fill=\"${q.fill}\" fill-opacity=\".92\" filter=\"url(#${id})\"/><path d=\"${d}\" fill=\"none\" stroke=\"${q.line}\" stroke-width=\"1.3\" stroke-linejoin=\"round\"/>`; }\n    if (outline) s += `<path d=\"${petal(R0 * outline[k] / 100, th)}\" fill=\"none\" stroke=\"${q.line}\" stroke-width=\"2\" stroke-dasharray=\"4 4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>`;\n    const [lx, ly] = P(R0 + 18, th).split(' ').map(Number), anchor = Math.abs(lx - c) < 12 ? 'middle' : lx > c ? 'start' : 'end';\n    s += `<text x=\"${(anchor === 'start' ? lx - 2 : anchor === 'end' ? lx + 2 : lx).toFixed(1)}\" y=\"${(ly + 4).toFixed(1)}\" text-anchor=\"${anchor}\" font-family=\"Manrope, sans-serif\" font-size=\"12\" font-weight=\"700\" fill=\"${q.line}\">${q.label}</text>`;\n  });\n  return s + `<circle cx=\"${c}\" cy=\"${c}\" r=\"4\" fill=\"#8C7F71\"/></svg>`;\n}\nconst WHEEL_LEGEND = `<div class=\"st-legend\"><span><i class=\"f\"></i>где ты сейчас</span><span><i class=\"d\"></i>куда тебе хочется</span></div>`;\n\n/* ---------- Остаться или нет (для тестов про жизнь после переезда) ---------- */\nconst STAY_Q = 'Ты хочешь остаться здесь жить?';\nconst STAY_OPTS = ['Да, я решила остаться', 'Скорее да, но иногда сомневаюсь', 'Пока не знаю, думаю', 'Скорее нет: хочу вернуться или переехать дальше', 'Это решаю не только я'];\n\n/* ---------- Telegram-канал: приглашение подписаться ---------- */\n// Украина → канал психолога (украинская аудитория); любая другая страна или не указана → канал коуча (швейцарская аудитория)\nfunction channelHtml(country){\n  const ua = country === 'Украина' || (!country && BRAND === 'psy'), P = AUTHOR[ua ? 'psy' : 'coach'];\n  return `<div class=\"blk channel\"><div class=\"eyebrow\">Telegram-канал</div><h2>Присоединяйся к моему каналу</h2>\n    <p>Канал совсем новый. Здесь собирается наша ${ua ? 'украинская' : 'швейцарская'} аудитория: ${ua ? 'те, кому важны тёплые и живые отношения' : 'те, кто живёт в Швейцарии и строит здесь свою жизнь'}. В планах делиться нужной информацией, находить поддержку и единомышленников. Буду рада, если ты будешь среди первых.</p>\n    <div class=\"invite-links\"><a href=\"${P.telegram}\" target=\"_blank\" rel=\"noopener\">Подписаться: ${P.telegram.replace('https://', '')}</a></div></div>`;\n}\n\n/* ---------- Пройди также ---------- */\nfunction testUrl(t){\n  if (typeof SITE_URL !== 'undefined' && SITE_URL) return SITE_URL.replace(/\\/?$/, '/') + t.path;\n  if (typeof TEST_LINKS !== 'undefined' && TEST_LINKS[t.id]) return TEST_LINKS[t.id];\n  return BASE + t.path;\n}\nfunction moreTestsHtml(currentId){\n  const list = TESTS.filter(t => t.id !== currentId);\n  if (!list.length) return '';\n  return `<div class=\"blk more\"><div class=\"eyebrow\">Пройди также</div>\n    <div class=\"tcards\">${list.map(t => `<a class=\"tcard ${t.brand}\" href=\"${testUrl(t)}\" target=\"_blank\" rel=\"noopener\">\n      <span class=\"ttag\">${t.tag}</span><b>${t.name}</b><span>${t.text}</span><span class=\"tgo\">Пройти тест →</span></a>`).join('')}</div></div>`;\n}\n\n/* ---------- Об этом опроснике + дисклеймер ---------- */\nconst DISCLAIMER = [\n  'Этот опросник — инструмент самопознания и разговора. Он не является психологической или медицинской диагностикой, психотерапевтическим заключением и не заменяет консультацию специалиста.',\n  'Результаты отражают твоё личное восприятие за последние 4 недели и могут меняться.',\n  'Если ты переживаешь кризис, насилие или угрозу своей безопасности, обратись к специалисту или в экстренные службы своей страны.'\n];\n/* Точка А → точка Б: если в TEST_INFO есть from / to / key — показываем, с чем человек приходит и с чем уходит. */\nfunction abHtml(){\n  if (typeof TEST_INFO === 'undefined' || !TEST_INFO.from) return '';\n  const ps = a => [].concat(a).map(x => `<p>${x}</p>`).join('');\n  return `<div class=\"ab\"><div class=\"ab-a\"><span class=\"ab-l\">Точка А · с чем ты приходишь</span>${ps(TEST_INFO.from)}</div>\n    <div class=\"ab-arrow\" aria-hidden=\"true\"><svg viewBox=\"0 0 40 24\" width=\"40\" height=\"24\"><path d=\"M2 12h32M26 4l8 8-8 8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></div>\n    <div class=\"ab-b\"><span class=\"ab-l\">Точка Б · с чем ты уходишь</span>${ps(TEST_INFO.to)}</div></div>\n    ${TEST_INFO.key ? `<div class=\"ab-key\"><b>Главное понимание</b><p>${TEST_INFO.key}</p></div>` : ''}`;\n}\nfunction testInfoHtml(){\n  if (typeof TEST_INFO === 'undefined') return '';\n  if (TEST_INFO.from) return `<div class=\"blk testinfo\"><div class=\"eyebrow\">Зачем проходить</div>\n    <p class=\"lead\">${TEST_INFO.why}</p>${abHtml()}\n    <div class=\"ti-cols\"><div><h3>Что с этим делать</h3><ul class=\"clean\">${TEST_INFO.next.map(x => `<li>${x}</li>`).join('')}</ul></div></div></div>`;\n  return `<div class=\"blk testinfo\"><div class=\"eyebrow\">Об этом опроснике</div>\n    <p class=\"lead\">${TEST_INFO.why}</p>\n    <div class=\"ti-cols\">\n      <div><h3>Что даёт прохождение</h3><ul class=\"clean\">${TEST_INFO.gives.map(x => `<li>${x}</li>`).join('')}</ul></div>\n      <div><h3>Что с этим делать</h3><ul class=\"clean\">${TEST_INFO.next.map(x => `<li>${x}</li>`).join('')}</ul></div>\n    </div></div>`;\n}\n/* Текст «Важно» сверяется по смыслу с каждым тестом: свой вариант — TEST_DISCLAIMER в meta.js (null = общая строка). */\nfunction disclaimerHtml(list){\n  const D = list || (typeof TEST_DISCLAIMER !== 'undefined' ? TEST_DISCLAIMER.map((x, i) => x || DISCLAIMER[i]).filter(Boolean) : DISCLAIMER);\n  return `<div class=\"disclaimer\"><b>Важно</b>${D.map(x => `<p>${x}</p>`).join('')}</div>`;\n}\n\n/* ---------- Поделиться тестом ---------- */\nconst SHARE_TEXT = {\n  'roza-lyubvi': ['Прошла тест «Роза любви» для пары — интересно и очень точно. Пройди и ты, потом сравним:',\n                  'Нашла тест «Роза любви»: 15 минут, и видно, какие роли в паре звучат ярко, а какие стали тише. Попробуй:'],\n  'kompas':      ['Прошла тест «Компас адаптации» для тех, кто живёт в эмиграции. Очень помогает понять, где ты сейчас. Попробуй:',\n                  'Нашла тест «Компас адаптации»: 10 минут, и видно, что уже стало опорой в новой стране, а где пока тихо. Попробуй:'],\n  'stupeni':     ['Прошла тест «Восемь ступеней к дому» — очень тёплый и точный, про то, как заново строишь жизнь после переезда. Попробуй:',\n                  'Нашла «Восемь ступеней к дому»: путеводитель и тест для тех, кто живёт в эмиграции. Видно, какие ступени держат, а какая поскрипывает. Пройди:',\n                  'Если ты тоже живёшь не в своей стране — пройди «Восемь ступеней к дому». Мне помогло понять, с чего начинать:']\n};\nconst SHARE_ICON = {\n  share: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 3v12M7 8l5-5 5 5M5 13v6a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>',\n  wa: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 20l1.2-4A8 8 0 1 1 8 18.8z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"M9 9.5c0 3 2.5 5.5 5.5 5.5l1-1.5-2-1-1 1c-1-.5-1.5-1-2-2l1-1-1-2z\" fill=\"currentColor\"/></svg>',\n  tg: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M21 4 3 11l6 2 2 6 3-4 5 4z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"m9 13 8-6\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>',\n  copy: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"8\" y=\"8\" width=\"12\" height=\"12\" rx=\"2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>'\n};\nfunction shareData(){\n  const t = TESTS.find(x => typeof TEST_META !== 'undefined' && x.id === TEST_META.id) || TESTS[0];\n  return { url: testUrl(t), text: pickOne(SHARE_TEXT[t.id] || ['Попробуй этот тест:']), title: t.name };\n}\nfunction shareHtml(compact){\n  if (typeof TEST_META === 'undefined') return '';\n  const head = compact\n    ? `<p class=\"note\">Знаешь, кому этот тест тоже может быть полезен? Перешли ссылку.</p>`\n    : `<div class=\"eyebrow\">Поделиться</div><h3>Перешли тест друзьям</h3><p>Если тест оказался полезным, отправь его тем, кому он тоже может помочь. ${TEST_META.id === 'roza-lyubvi' ? 'А ещё лучше — предложи пройти партнёру и сравните результаты.' : 'Особенно тем, кто тоже недавно переехал.'}</p>`;\n  return `<div class=\"${compact ? 'share compact' : 'blk share'}\">${head}\n    <div class=\"share-btns\">\n      ${navigator.share ? `<button type=\"button\" class=\"main\" data-share-act=\"native\">${SHARE_ICON.share}Поделиться</button>` : ''}\n      <button type=\"button\" data-share-act=\"wa\">${SHARE_ICON.wa}WhatsApp</button>\n      <button type=\"button\" data-share-act=\"tg\">${SHARE_ICON.tg}Telegram</button>\n      <button type=\"button\" data-share-act=\"copy\">${SHARE_ICON.copy}Скопировать ссылку</button>\n    </div>\n    <div class=\"share-link\" hidden><input readonly aria-label=\"Ссылка на тест\"></div>\n    <span class=\"share-ok\" hidden></span></div>`;\n}\nfunction openExternal(url){\n  const w = window.open(url, '_blank', 'noopener');\n  if (!w) location.href = url;\n}\ndocument.addEventListener('click', async (ev) => {\n  const b = ev.target.closest('[data-share-act]'); if (!b) return;\n  const box = b.closest('.share'), d = shareData(), act = b.dataset.shareAct;\n  const ok = box.querySelector('.share-ok');\n  const showOk = t => { ok.textContent = t; ok.hidden = false; setTimeout(() => ok.hidden = true, 4000); };\n  if (act === 'native'){\n    try { await navigator.share({ title: d.title, text: d.text, url: d.url }); return; }\n    catch(e){ if (e && e.name === 'AbortError') return; }\n  }\n  if (act === 'wa') return openExternal('https://wa.me/?text=' + encodeURIComponent(d.text + ' ' + d.url));\n  if (act === 'tg') return openExternal('https://t.me/share/url?url=' + encodeURIComponent(d.url) + '&text=' + encodeURIComponent(d.text));\n  try { await navigator.clipboard.writeText(d.text + ' ' + d.url); showOk('Ссылка скопирована. Вставь её в сообщение другу.'); }\n  catch(e){\n    const row = box.querySelector('.share-link'), inp = row.querySelector('input');\n    inp.value = d.url; row.hidden = false; inp.focus(); inp.select();\n    showOk('Скопируй ссылку из поля выше.');\n  }\n});\n\n/* ---------- Отрисовка общих блоков на странице ---------- */\ndocument.documentElement.dataset.brand = BRAND;\ndocument.querySelectorAll('[data-author]').forEach(el => el.innerHTML = authorHtml());\ndocument.querySelectorAll('[data-greeting]').forEach(el => el.innerHTML = greetingHtml());\ndocument.querySelectorAll('[data-testinfo]').forEach(el => el.innerHTML = testInfoHtml());\ndocument.querySelectorAll('[data-disclaimer]').forEach(el => el.innerHTML = disclaimerHtml());\n/* копирайт внизу каждой страницы сайта */\n(function(){ const w = document.querySelector('.wrap'); if (!w || w.querySelector('.copy')) return;\n  const f = document.createElement('footer'); f.className = 'copy'; f.textContent = '© ' + new Date().getFullYear() + ' Ирина Вознесенская. Все права защищены.'; w.appendChild(f); })();\ndocument.querySelectorAll('[data-share]').forEach(el => el.innerHTML = shareHtml(el.dataset.share === 'compact'));\n(function(){\n  const go = document.getElementById('svGo'); if (!go) return;\n  try { (JSON.parse(localStorage.getItem('irinaTestsSurvey') || '[]') || []).forEach(id => { const c = document.getElementById(id); if (c) c.checked = true; }); } catch(e){}\n  go.addEventListener('click', () => {\n    const a = surveyAnswers(), err = document.getElementById('svErr');\n    const miss = !a.heard.length ? 'Отметь, пожалуйста, откуда ты обо мне знаешь.' : !a.interest.length ? 'Отметь, пожалуйста, что тебе интересно.' : '';\n    err.textContent = miss; err.hidden = !miss;\n    if (miss) return;\n    try { localStorage.setItem('irinaTestsSurvey', JSON.stringify([...document.querySelectorAll('input[data-sv]:checked')].map(i => i.id))); } catch(e){}\n    document.querySelector('[data-greeting]').hidden = true;\n    document.getElementById('testStart').hidden = false;\n    window.scrollTo(0, 0);\n  });\n})();\n\n/* ---------- превью отчёта веером (стартовая страница теста) ---------- */\n(function(){\n  const host = document.querySelector('[data-reportfan]');\n  if (!host || typeof REPORT_FAN === 'undefined' || !window.RP_IMG || !RP_IMG.length) return;\n  const F = REPORT_FAN, N = Math.min(F.items.length, RP_IMG.length);\n  const calm = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;\n  host.className = 'rf';\n  host.innerHTML = `<div class=\"rf-head\"><div class=\"eyebrow\">Твой личный разбор · PDF</div><h3>${F.title}</h3><p>${F.lead}</p></div>\n    <div class=\"rf-stage stacked\" role=\"group\" aria-label=\"Страницы примера отчёта\">\n      ${F.items.slice(0, N).map((it, i) => `<button type=\"button\" class=\"rf-page\" data-i=\"${i}\" aria-label=\"Страница: ${it.t}\"><img src=\"${RP_IMG[i]}\" alt=\"Пример страницы отчёта: ${it.t}\" loading=\"lazy\" draggable=\"false\"></button>`).join('')}\n      <span class=\"rf-badge\">${F.pages}<small>страниц</small></span>\n    </div>\n    <div class=\"rf-cap\" aria-live=\"polite\"></div>\n    <div class=\"rf-nav\"><button type=\"button\" class=\"rf-arrow\" data-d=\"-1\" aria-label=\"Предыдущая страница\">‹</button><div class=\"rf-dots\">${F.items.slice(0, N).map((_, i) => `<span data-i=\"${i}\"></span>`).join('')}</div><button type=\"button\" class=\"rf-arrow\" data-d=\"1\" aria-label=\"Следующая страница\">›</button></div>\n    <p class=\"rf-hint\">Нажми на страницу в центре, чтобы рассмотреть её поближе.</p>`;\n  const stage = host.querySelector('.rf-stage'), pages = [...host.querySelectorAll('.rf-page')], dots = [...host.querySelectorAll('.rf-dots span')], cap = host.querySelector('.rf-cap');\n  let cur = 0, timer = null;\n  function lay(){\n    const w = stage.clientWidth, deg = w < 420 ? 8 : 10;\n    pages.forEach((p, i) => {\n      let o = i - cur; if (o > N / 2) o -= N; if (o < -N / 2) o += N;\n      const a = Math.abs(o);\n      p.style.transform = `translateX(-50%) rotate(${o * deg}deg) translateY(${o ? a * 4 : -16}px) scale(${o ? 1 - a * .04 : 1.03})`;\n      p.style.zIndex = 10 - a; p.classList.toggle('on', !o);\n      p.tabIndex = o ? -1 : 0;\n    });\n    dots.forEach((d, i) => d.classList.toggle('on', i === cur));\n    cap.innerHTML = `<b>${F.items[cur].t}</b><span>${F.items[cur].d}</span>`;\n  }\n  function go(i, user){ cur = (i + N) % N; lay(); if (user) stop(); }\n  function stop(){ if (timer) clearInterval(timer); timer = null; }\n  pages.forEach((p, i) => p.addEventListener('click', () => i === cur ? zoom(i) : go(i, true)));\n  dots.forEach((d, i) => d.addEventListener('click', () => go(i, true)));\n  host.querySelectorAll('.rf-arrow').forEach(b => b.addEventListener('click', () => go(cur + +b.dataset.d, true)));\n  let sx = null; stage.addEventListener('touchstart', e => { sx = e.touches[0].clientX; }, { passive: true });\n  stage.addEventListener('touchend', e => { if (sx == null) return; const dx = e.changedTouches[0].clientX - sx; if (Math.abs(dx) > 40) go(cur + (dx < 0 ? 1 : -1), true); sx = null; });\n  function zoom(i){\n    const box = document.createElement('div'); box.className = 'rf-zoom'; box.setAttribute('role', 'dialog'); box.setAttribute('aria-label', F.items[i].t);\n    box.innerHTML = `<figure><img src=\"${RP_IMG[i]}\" alt=\"Пример страницы отчёта: ${F.items[i].t}\"><figcaption>${F.items[i].t} · пример</figcaption></figure><button type=\"button\" class=\"rf-x\" aria-label=\"Закрыть\">×</button>`;\n    const close = () => { box.remove(); document.removeEventListener('keydown', esc); };\n    const esc = e => { if (e.key === 'Escape') close(); };\n    box.addEventListener('click', close); document.addEventListener('keydown', esc);\n    document.body.appendChild(box); box.querySelector('.rf-x').focus();\n  }\n  lay(); window.addEventListener('resize', lay);\n  const open = () => { stage.classList.remove('stacked'); if (!calm && !timer) timer = setInterval(() => go(cur + 1), 3800); };\n  if ('IntersectionObserver' in window && !calm) {\n    const io = new IntersectionObserver(es => { if (es.some(e => e.isIntersecting)) { setTimeout(open, 250); io.disconnect(); } }, { threshold: .35 });\n    io.observe(stage);\n  } else open();\n  host.addEventListener('pointerenter', stop);\n})();\n", "/* ---------- схемы «Компаса адаптации» ----------\n   Простые линейные схемы на фоне страницы: тонкие линии, один акцентный цвет, без картинок. */\nconst LN = { ink:'#3A322B', muted:'#9A8D7E', line:'#D8CDBE', acc:'#8A5A3B', soft:'#EFE6D8' };\nconst sf = (x, y, t, o = {}) => `<text x=\"${x}\" y=\"${y}\" text-anchor=\"${o.a || 'middle'}\" font-family=\"${o.serif ? 'Forum, Georgia, serif' : 'Manrope, sans-serif'}\" font-size=\"${o.s || 12}\" font-weight=\"${o.w || 400}\" fill=\"${o.c || LN.ink}\" ${o.ls ? `letter-spacing=\"${o.ls}\"` : ''}>${t}</text>`;\n\n/* Обложка: тонкий компас */\nfunction compassSVG(){\n  const c = 70;\n  let s = `<svg viewBox=\"0 0 140 140\" role=\"img\" aria-label=\"Компас\" width=\"150\" height=\"150\">\n    <circle cx=\"${c}\" cy=\"${c}\" r=\"60\" fill=\"none\" stroke=\"${LN.ink}\" stroke-width=\"1.2\"/>\n    <circle cx=\"${c}\" cy=\"${c}\" r=\"52\" fill=\"none\" stroke=\"${LN.line}\" stroke-width=\"1\"/>`;\n  for (let k = 0; k < 24; k++){ const a = k * Math.PI / 12, r1 = k % 6 === 0 ? 44 : 49; s += `<line x1=\"${(c + r1 * Math.cos(a)).toFixed(1)}\" y1=\"${(c + r1 * Math.sin(a)).toFixed(1)}\" x2=\"${(c + 52 * Math.cos(a)).toFixed(1)}\" y2=\"${(c + 52 * Math.sin(a)).toFixed(1)}\" stroke=\"${LN.ink}\" stroke-width=\"${k % 6 === 0 ? 1.2 : .7}\"/>`; }\n  s += `<path d=\"M${c} ${c - 38} L${c + 7} ${c} L${c} ${c + 38} L${c - 7} ${c}Z\" fill=\"none\" stroke=\"${LN.ink}\" stroke-width=\"1.1\"/>\n    <path d=\"M${c} ${c - 38} L${c + 7} ${c} L${c - 7} ${c}Z\" fill=\"${LN.acc}\"/>\n    <circle cx=\"${c}\" cy=\"${c}\" r=\"3\" fill=\"${LN.ink}\"/>` + sf(c, 20, 'С', { serif:true, s:12 });\n  return s + '</svg>';\n}\n\n/* Две культуры: схема 2 × 2 и точка — где человек сейчас */\nfunction shoresSVG(own, neu){\n  const W = 520, H = 420, x0 = 90, y0 = 30, S = 340;               // поле S×S\n  const px = x0 + S * neu / 20, py = y0 + S * (1 - own / 20);\n  const q = [['Свой остров', 0, 0], ['Мост между мирами', 1, 0], ['Между двумя берегами', 0, 1], ['Новая жизнь с чистого листа', 1, 1]];\n  const mine = (own >= 10 ? 0 : 1) * 2 + (neu >= 10 ? 1 : 0);\n  // цвета по спирали: своя культура — фиолетовый, мост — бирюзовый, между берегами — бежевый, новая культура — жёлтый\n  const QF = ['#EDEBF8', '#E1F5F6', '#F3F1EC', '#F9F5DE'], QL = ['#6A5FB8', '#2894A0', '#8E8470', '#A99A2E'];\n  let s = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Схема: своя и новая культура\">`;\n  q.forEach(([t, cx, cy], i) => {\n    const x = x0 + cx * S / 2, y = y0 + cy * S / 2;\n    s += `<rect x=\"${x}\" y=\"${y}\" width=\"${S / 2}\" height=\"${S / 2}\" fill=\"${QF[i]}\" opacity=\"${i === mine ? 1 : .35}\"/>`;\n    const words = t.split(' '), mid = Math.ceil(words.length / 2);\n    const l1 = words.length > 2 ? words.slice(0, mid).join(' ') : t, l2 = words.length > 2 ? words.slice(mid).join(' ') : '';\n    s += sf(x + S / 4, y + S / 4 - (l2 ? 4 : -4), l1, { serif:true, s:19, c: i === mine ? QL[i] : LN.muted });\n    if (l2) s += sf(x + S / 4, y + S / 4 + 20, l2, { serif:true, s:19, c: i === mine ? QL[i] : LN.muted });\n  });\n  s += `<rect x=\"${x0}\" y=\"${y0}\" width=\"${S}\" height=\"${S}\" fill=\"none\" stroke=\"${LN.ink}\" stroke-width=\"1\"/>\n    <line x1=\"${x0 + S / 2}\" y1=\"${y0}\" x2=\"${x0 + S / 2}\" y2=\"${y0 + S}\" stroke=\"${LN.line}\" stroke-dasharray=\"3 4\"/>\n    <line x1=\"${x0}\" y1=\"${y0 + S / 2}\" x2=\"${x0 + S}\" y2=\"${y0 + S / 2}\" stroke=\"${LN.line}\" stroke-dasharray=\"3 4\"/>`;\n  [0, 10, 20].forEach(v => {\n    s += sf(x0 + S * v / 20, y0 + S + 18, v, { c:LN.muted, s:11 }) + sf(x0 - 10, y0 + S * (1 - v / 20) + 4, v, { a:'end', c:LN.muted, s:11 });\n  });\n  s += sf(x0 + S / 2, y0 + S + 42, 'связь с новой культурой →', { c:LN.muted, s:12, ls:'.5' });\n  s += `<text transform=\"translate(${x0 - 40} ${y0 + S / 2}) rotate(-90)\" text-anchor=\"middle\" font-family=\"Manrope, sans-serif\" font-size=\"12\" letter-spacing=\".5\" fill=\"${LN.muted}\">связь со своей культурой →</text>`;\n  s += `<line x1=\"${px}\" y1=\"${y0 + S}\" x2=\"${px}\" y2=\"${py}\" stroke=\"${QL[mine]}\" stroke-dasharray=\"2 3\"/><line x1=\"${x0}\" y1=\"${py}\" x2=\"${px}\" y2=\"${py}\" stroke=\"${QL[mine]}\" stroke-dasharray=\"2 3\"/>\n    <circle cx=\"${px}\" cy=\"${py}\" r=\"9\" fill=\"${QL[mine]}\"/><circle cx=\"${px}\" cy=\"${py}\" r=\"15\" fill=\"none\" stroke=\"${QL[mine]}\" stroke-width=\"1\"/>`;\n  s += sf(px + (px > x0 + S - 60 ? -22 : 22), py - 16, 'ты здесь', { a: px > x0 + S - 60 ? 'end' : 'start', c:QL[mine], w:700, s:15 });\n  return s + '</svg>';\n}\n\n/* Шесть сфер: дорожки 0–20, каждая сфера в своей рамке */\nfunction flowerSVG(sc){\n  const W = 560, rowH = 56, H = 30 + rowH * sc.length, x0 = 168, x1 = 486;\n  let s = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Шесть сфер\">`;\n  const max = Math.max(...sc), min = Math.min(...sc);\n  sc.forEach((v, k) => {\n    const y = 30 + k * rowH, x = x0 + (x1 - x0) * v / 20, hi = v === max || v === min;\n    const col = css(AC[k]), soft = css(AS[k]);\n    s += `<rect x=\"4\" y=\"${y - 22}\" width=\"${W - 8}\" height=\"44\" rx=\"10\" fill=\"${soft}\" stroke=\"${col}\" stroke-width=\"1.2\"/>`;\n    s += `<g transform=\"translate(20 ${y - 12})\">${aIcon(k).replace(/^<svg[^>]*>/, '').replace(/<\\/svg>$/, '')}</g>`;\n    s += sf(54, y + 6, AREAS[k].short, { a:'start', serif:true, s:19, c: col });\n    [5, 10, 15].forEach(t => { const tx = x0 + (x1 - x0) * t / 20; s += `<line x1=\"${tx}\" y1=\"${y - 7}\" x2=\"${tx}\" y2=\"${y + 7}\" stroke=\"${col}\" stroke-width=\".8\" opacity=\".35\"/>`; });\n    s += `<line x1=\"${x0}\" y1=\"${y}\" x2=\"${x1}\" y2=\"${y}\" stroke=\"#fff\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n      <line x1=\"${x0}\" y1=\"${y}\" x2=\"${x}\" y2=\"${y}\" stroke=\"${col}\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n      <circle cx=\"${x}\" cy=\"${y}\" r=\"${hi ? 9 : 7}\" fill=\"${col}\" stroke=\"#fff\" stroke-width=\"2\"/>`;\n    s += sf(x1 + 18, y + 6, `${v}/20`, { a:'start', s:14, w:700, c: col });\n  });\n  [0, 10, 20].forEach(v => { const x = x0 + (x1 - x0) * v / 20; s += sf(x, H - 2, v, { c:LN.muted, s:10 }); });\n  return s + '</svg>';\n}\n\n/* Путь адаптации: линия с этапами */\nfunction journeySVG(stage){\n  const W = 560, H = 190;\n  const P = [[50, 60], [200, 140], [360, 100], [510, 40]], names = ['Открытия','Трудности','Опоры','Как дома'];\n  let s = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Путь адаптации\">`;\n  s += `<path d=\"M50 60 C110 60 140 140 200 140 S310 100 360 100 S460 40 510 40\" fill=\"none\" stroke=\"${LN.ink}\" stroke-width=\"1.4\"/>`;\n  if (stage === 4) s += `<path d=\"M360 100 C390 150 300 175 280 140 C265 112 320 95 360 100\" fill=\"none\" stroke=\"${LN.acc}\" stroke-width=\"1.4\" stroke-dasharray=\"4 4\"/>`;\n  P.forEach(([x, y], i) => {\n    const on = i === stage;\n    s += `<circle cx=\"${x}\" cy=\"${y}\" r=\"${on ? 9 : 6}\" fill=\"${on ? LN.acc : '#fff'}\" stroke=\"${on ? LN.acc : LN.ink}\" stroke-width=\"1.4\"/>`;\n    s += sf(x, y + (i === 1 ? 30 : 28), names[i], { serif:true, s:16, c: on ? LN.acc : LN.ink });\n  });\n  const at = stage === 4 ? [300, 165] : P[stage];\n  s += sf(at[0], at[1] - 18, stage === 4 ? 'новый виток · ты здесь' : 'ты здесь', { s:12, w:700, c:LN.acc, ls:'.4' });\n  return s + '</svg>';\n}\n", "/* =====================================================================\n   «Компас адаптации» — коучинговый самотест про адаптацию в эмиграции.\n   ===================================================================== */\nconst AREAS = [\n  { name: 'Язык и общение', short: 'Язык',\n    items: ['Я говорю на местном языке в повседневных ситуациях, даже если с ошибками.',\n            'Я учу язык: занятия, приложение, книги, сериалы.',\n            'Я сама или сам начинаю разговор с местными людьми, а не только отвечаю на вопросы.',\n            'Я читаю письма, сайты и объявления на местном языке без переводчика или с минимальной помощью.',\n            'Я переспрашиваю и прошу объяснить, если чего-то не понимаю, вместо того чтобы молчать.'],\n    lv: ['Язык пока звучит тихо. Это нормально: язык — одна из самых больших нагрузок в эмиграции, и многим нужно время, чтобы начать говорить без страха. Каждый маленький разговор уже шаг.',\n         'Язык в процессе: ты уже пользуешься им, но, возможно, ещё с напряжением или только в знакомых ситуациях. Сейчас важна регулярность, а не идеальность.',\n         'Язык — твоя опора. Ты говоришь, учишься и не боишься ошибок. Это открывает двери ко всему остальному: работе, людям и чувству, что ты здесь не гость.'],\n    recs: ['Выбери одну ситуацию в неделю, где говоришь только на местном языке: кафе, магазин, соседи.',\n           '15 минут языка каждый день лучше, чем два часа раз в неделю. Подойдут сериал, подкаст или приложение.',\n           'Найди языкового партнёра или разговорный клуб: там все учатся и ошибаются вместе.'],\n    focus: 'заговорить на новом языке смелее' },\n  { name: 'Быт и система', short: 'Быт',\n    items: ['Я спокойно разбираюсь с документами, письмами, страховкой и счетами.',\n            'Я знаю, куда обратиться, если что-то случилось: врач, администрация, страховая, юрист.',\n            'Я пользуюсь местными сервисами: транспорт, банк, почта, приложения.',\n            'Я понимаю местные правила и негласные нормы и следую им без внутреннего протеста.',\n            'Я делаю свой дом уютным: вещи, порядок и мелочи, которые мне нравятся.'],\n    lv: ['Быт и система пока даются непросто. Письма, документы и правила новой страны могут пугать и забирать много сил. С этим сталкиваются почти все, кто переезжает.',\n         'В быту ты уже ориентируешься, но некоторые вещи всё ещё вызывают тревогу или требуют много сил. Ещё немного опыта, и система станет понятнее.',\n         'Быт и система — твоя опора. Ты знаешь, как всё устроено, и действуешь уверенно. Это освобождает силы для того, что действительно важно.'],\n    recs: ['Заведи одну папку для всех документов и писем и разбирай её раз в неделю, в одно и то же время.',\n           'Составь список «куда звонить, если…»: врач, страховка, администрация, экстренные службы.',\n           'Спроси у местных или у тех, кто давно здесь живёт, о негласных правилах. Многое проще, чем кажется.'],\n    focus: 'чувствовать себя увереннее в новой системе' },\n  { name: 'Дело и реализация', short: 'Дело',\n    items: ['Я делаю шаги к работе или делу, которые мне подходят: учёба, резюме, проекты, собеседования.',\n            'Я использую свои навыки и опыт, а не только делаю то, что подвернулось.',\n            'Я узнаю, как устроен рынок труда и моя профессия в новой стране.',\n            'Я довожу начатое до конца и вижу результат своих усилий.',\n            'Я говорю о своих умениях и достижениях вслух, не преуменьшая их.'],\n    lv: ['Дело и реализация сейчас звучат тихо. После переезда многие временно теряют профессиональную опору, и это одна из самых чувствительных тем. Важно помнить: твой опыт никуда не исчез.',\n         'Ты двигаешься в сторону своего дела, но, возможно, пока не там, где хочется, или используешь не всё, что умеешь. Это промежуточный этап, и у него есть выход.',\n         'Дело и реализация — твоя опора. Ты используешь свои сильные стороны и видишь результат. Это даёт уверенность и чувство, что ты на своём месте.'],\n    recs: ['Выпиши 10 своих умений и достижений, в том числе из прошлой жизни. Перечитывай перед важными разговорами.',\n           'Поговори с двумя людьми, которые уже работают в твоей сфере в этой стране. Спроси, с чего они начинали.',\n           'Поставь одну маленькую цель на месяц: курс, резюме, проект или встреча.'],\n    focus: 'найти дело, в котором ты раскроешься' },\n  { name: 'Люди и связи', short: 'Люди',\n    items: ['Я встречаюсь с друзьями или знакомыми в новой стране вживую.',\n            'Я общаюсь с местными людьми, а не только с русскоязычными.',\n            'Я поддерживаю связь с близкими на родине так, что мне от этого тепло, а не тяжело.',\n            'Я участвую в чём-то вместе с другими: курсы, клубы, волонтёрство, спорт, родительские чаты.',\n            'Я делюсь своими переживаниями хотя бы с одним человеком и получаю поддержку.'],\n    lv: ['Связи с людьми сейчас звучат тихо. Одиночество — частый спутник эмиграции, даже когда рядом семья. Новые связи строятся медленно, и это ничего плохого о тебе не говорит.',\n         'Люди вокруг тебя есть, но, возможно, не хватает глубины или разнообразия: только свои или только по работе. Здесь легко сделать следующий шаг.',\n         'Люди и связи — твоя опора. Тебе есть с кем разделить радость и трудности, и в старой, и в новой жизни. Это одна из самых сильных защит от стресса.'],\n    recs: ['Выбери одно регулярное занятие с другими людьми: спорт, хор, курс, волонтёрство. Регулярность рождает дружбу.',\n           'Пригласи кого-то на кофе первым. Многие тоже ждут, когда их позовут.',\n           'Договорись о постоянном времени для звонков близким на родине, чтобы связь была тёплой, а не тревожной.'],\n    focus: 'найти своих людей в новой стране' },\n  { name: 'Ресурс: тело и отдых', short: 'Ресурс',\n    items: ['Я высыпаюсь и просыпаюсь с силами.',\n            'Я двигаюсь: прогулки, спорт, природа.',\n            'Я делаю что-то только для удовольствия, без пользы и цели.',\n            'Я замечаю, когда устаю, и даю себе отдых, а не «дотягиваю».',\n            'Я выбираюсь в красивые места новой страны и наслаждаюсь ими.'],\n    lv: ['Ресурса сейчас мало. Адаптация забирает очень много энергии, и тело часто первым подаёт сигнал усталости. Это не слабость, а знак, что тебе нужна забота.',\n         'Ты заботишься о себе, но не всегда. Когда становится трудно, отдых и удовольствие уходят первыми. Стоит сделать их частью расписания.',\n         'Тело и отдых — твоя опора. Ты умеешь отдыхать, двигаться и радоваться. Это топливо для всех остальных сфер.'],\n    recs: ['Добавь в каждый день одно маленькое удовольствие без пользы: кофе на балконе, музыка, прогулка.',\n           'Двигайся хотя бы 20 минут в день. Прогулка тоже считается.',\n           'Раз в неделю открывай новое красивое место в стране. Так новая страна понемногу становится твоей.'],\n    focus: 'вернуть себе силы и радость' },\n  { name: 'Я и смысл', short: 'Смысл',\n    items: ['Я делаю то, что важно лично мне, а не только то, что «надо».',\n            'Я представляю, какой хочу видеть свою жизнь здесь через год, и делаю к этому шаги.',\n            'Я замечаю, что во мне выросло и изменилось благодаря переезду.',\n            'Я принимаю решения, опираясь на свои ценности, а не на чужие ожидания.',\n            'Я позволяю себе быть собой: говорю, одеваюсь, отдыхаю так, как мне по душе.'],\n    lv: ['Ощущение себя и смысла сейчас звучит тихо. После переезда многие чувствуют, что потеряли часть себя: прежние роли, статус, привычные опоры. Это время, когда можно заново собрать себя.',\n         'Ты ищешь себя в новой жизни и уже находишь опоры. Иногда возвращается ощущение, что живёшь не своей жизнью. Это часть пути.',\n         'Ты остаёшься собой и живёшь по своим ценностям. Переезд стал не только испытанием, но и ростом. Это самая глубокая опора адаптации.'],\n    recs: ['Каждый вечер записывай одно дело, которое сегодня было важно именно тебе.',\n           'Опиши, какой хочешь видеть свою жизнь здесь через год. Выбери один шаг к этому.',\n           'Вспомни, что давало тебе силы до переезда. Что из этого можно вернуть здесь?'],\n    focus: 'найти себя и своё место в новом мире' }\n];\nconst CULT = [\n  { name: 'Связь со своей культурой',\n    items: ['Я говорю на родном языке дома или с друзьями.',\n            'Я готовлю привычную еду, отмечаю праздники и традиции своей культуры.',\n            'Я читаю, смотрю или слушаю что-то на родном языке.',\n            'Я общаюсь с людьми из своей культуры в новой стране.',\n            'Я передаю детям или близким что-то важное из своей культуры.'] },\n  { name: 'Связь с новой культурой',\n    items: ['Я пробую местную еду, праздники и обычаи.',\n            'Я смотрю местные новости и фильмы, слушаю местную музыку.',\n            'Я хожу на местные события: ярмарки, фестивали, собрания.',\n            'Я общаюсь с местными людьми вне работы.',\n            'Я узнаю историю и особенности страны, в которой живу.'] }\n];\nconst YEARS = ['меньше 6 месяцев','6–12 месяцев','1–3 года','3–5 лет','больше 5 лет'];\nconst STAGES = [\n  { phrase: 'Всё ново и интересно, вокруг много открытий.', name: 'Время открытий',\n    text: 'Всё ново и вдохновляет. Это прекрасное время, чтобы заложить опоры: язык, знакомства, привычки. Со временем вдохновение может смениться усталостью, и это нормальная часть пути.' },\n  { phrase: 'Стало сложнее: много усталости, раздражения, хочется домой.', name: 'Время трудностей',\n    text: 'Сейчас может быть непросто: усталость, раздражение, тоска по дому. Это самый частый и самый естественный этап адаптации. Он проходит, особенно когда рядом есть поддержка.' },\n  { phrase: 'Я постепенно привыкаю, нахожу свои способы и опоры.', name: 'Время опор',\n    text: 'Ты постепенно находишь свои способы жить здесь. Трудности ещё бывают, но опор становится больше. Сейчас хорошо укреплять то, что уже работает.' },\n  { phrase: 'Здесь мой дом, я могу быть собой.', name: 'Как дома',\n    text: 'Здесь твой дом, и ты можешь быть собой. Это результат большого пути. Теперь можно думать не только о том, как справиться, но и о том, чего тебе хочется.' },\n  { phrase: 'После спокойного периода снова стало непросто.', name: 'Новый виток',\n    text: 'После периода стабильности снова стало непросто. Так бывает: адаптация идёт не по прямой, а волнами. Новая волна — не откат назад, а приглашение к следующему шагу.' }\n];\nconst STRATEGY = {\n  both: ['Мост между мирами', 'Ты бережно хранишь свою культуру и одновременно открываешься новой. В психологии адаптации это называют интеграцией, и это самый устойчивый путь: у тебя есть и корни, и крылья. Важно продолжать держать оба берега и не уставать от двойной нагрузки.'],\n  newOnly: ['Новая жизнь с чистого листа', 'Ты активно входишь в новую культуру, а связь со своей стала тише. Это помогает быстро освоиться. Иногда вместе с прошлым уходит и часть опоры. Подумай, что из своей культуры тебе хочется сохранить для себя и близких.'],\n  ownOnly: ['Свой остров', 'Ты бережёшь свою культуру, язык и привычки, а новая страна пока остаётся немного в стороне. Это даёт безопасность и тепло. Следующий шаг — понемногу открывать мосты к новой культуре, не теряя своего.'],\n  none: ['Между двумя берегами', 'Сейчас связь и со своей, и с новой культурой звучит тихо. Так часто бывает в периоды усталости или сразу после переезда, когда сил хватает только на главное. Это не навсегда. Даже маленькие шаги к людям и традициям, своим и новым, помогают почувствовать опору.']\n};\nconst LV_NAME = ['пока звучит тихо','в процессе','твоя опора'];\nconst KF = ['#EEA9B3','#A6C4F0','#F2C6A8','#B0DCC0','#E2DCD0','#9ADDE0'], KL = ['#C25468','#3F6FBF','#C97E52','#4E9A70','#8E8470','#2894A0'];\nconst KSOFT = KF.map(c => '#' + [1,3,5].map(i => Math.round(parseInt(c.substr(i,2),16) * .45 + 255 * .55).toString(16).padStart(2,'0')).join(''));\nconst K_STAY = [\n  ['Решение принято', 'Ты решила остаться. Это одна из самых сильных опор адаптации: силы больше не утекают в вопрос «а может, не здесь?», а идут на то, чтобы обустраиваться. Даже если какие-то сферы ещё звучат тихо, у тебя уже есть главное — направление.'],\n  ['Скорее да, но сомнение возвращается', 'Ты в основном здесь, но сомнение иногда возвращается. Стоит замечать, когда именно оно приходит: часто оно говорит не о стране, а о сфере, которая в этот момент звучит тихо. Усталость, одиночество, неудача на работе звучат как «может, зря мы уехали». Укрепишь сферу — сомнение станет тише.'],\n  ['Ты ещё не решила', 'Ты ещё не решила, остаться ли, и это честно. Но жизнь «между» дорого стоит: трудно вкладываться в язык, людей и дело, когда не знаешь, надолго ли ты здесь. Исследователи миграции замечают, что решение складывается из того, насколько сильны связи здесь и там. Решать прямо сегодня не обязательно. Но можно назначить себе срок и прожить эти месяцы набело, а не на чемоданах.'],\n  ['Ты думаешь вернуться или уехать дальше', 'Ты думаешь вернуться или переехать дальше, и это нормальный выбор. Но даже временная жизнь остаётся жизнью. Язык, люди, силы и смысл нужны и той, кто здесь на год. А то, что ты построишь сейчас, ты увезёшь с собой.'],\n  ['Решение зависит не только от тебя', 'Решение остаться или уехать зависит не только от тебя: от работы мужа, от документов, от обстоятельств. Это одна из самых тяжёлых форм неопределённости. Помогает различать, что от тебя не зависит, что можно обсудить, и что твоё прямо сейчас, при любом решении.']\n];\nconst K_STAY_SHORT = ['решила остаться', 'скорее остаётся', 'ещё не решила', 'думает уехать', 'решает не только она'];\nconst K_GOAL_HINT = ['говорить на языке без страха', 'спокойно разбираться с письмами и документами', 'найти работу по профессии', 'найти одну близкую подругу', 'высыпаться и больше двигаться', 'делать то, что важно мне'];\nconst K_SAVE = 'irinaTests.kompas.v1';\nconst KEEP = 'Эта сфера уже работает на тебя. Сохраняй то, что делаешь, и опирайся на неё, когда становится трудно.';\nconst LABELS = ['ни разу','1–2 раза','иногда','часто','почти всегда'];\nconst AC = ['--a0','--a1','--a2','--a3','--a4','--a5'];\nconst AS = ['--a0s','--a1s','--a2s','--a3s','--a4s','--a5s'];\n\n/* ---------- состояние ---------- */\n// шаги: 0 — о переезде; 1–3 — по две сферы; 4 — две культуры\nlet goals = AREAS.map(() => null), goalText = AREAS.map(() => ''), finished = false;\nlet step = 0, ctx = { years: null, stage: null, stay: null }, ans = { areas: AREAS.map(() => Array(5).fill(null)), cult: CULT.map(() => Array(5).fill(null)) };\nlet myName = '', last = null;\nconst $ = id => document.getElementById(id);\nconst css = v => getComputedStyle(document.documentElement).getPropertyValue(v).trim();\nconst sum = a => a.reduce((x, y) => x + y, 0);\nconst esc = s => String(s).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst lvl = s => s <= 7 ? 0 : s <= 13 ? 1 : 2;\nconst TOTAL = 5 * 6 + 10 + 3 + 6;\n\n$('startBtn').addEventListener('click', () => {\n  myName = $('nameMe').value.trim();\n  resetInvite(); window.__leadCountry = '';\n  step = 0; ctx = { years: null, stage: null, stay: null }; goals = AREAS.map(() => null); goalText = AREAS.map(() => ''); finished = false;\n  ans = { areas: AREAS.map(() => Array(5).fill(null)), cult: CULT.map(() => Array(5).fill(null)) };\n  $('intro').hidden = true; $('quiz').hidden = false; renderStep(); window.scrollTo(0, 0);\n});\n\nfunction choiceGroup(title, opts, key){\n  const wrap = document.createElement('div'); wrap.className = 'q';\n  wrap.innerHTML = `<p>${title}</p><div class=\"choices1\" role=\"group\"></div>`;\n  const g = wrap.querySelector('.choices1');\n  opts.forEach((o, i) => {\n    const b = document.createElement('button'); b.className = 'opt1'; b.id = `c-${key}-${i}`; b.textContent = o;\n    b.setAttribute('aria-pressed', ctx[key] === i ? 'true' : 'false');\n    b.addEventListener('click', () => { ctx[key] = i; g.querySelectorAll('.opt1').forEach((x, n) => x.setAttribute('aria-pressed', n === i ? 'true' : 'false')); update(); });\n    g.appendChild(b);\n  });\n  return wrap;\n}\nfunction scaleItem(text, num, arr, i, idPrefix){\n  const q = document.createElement('div'); q.className = 'q';\n  q.innerHTML = `<p><span class=\"n\">${num}.</span>${text}</p><div class=\"opts\" role=\"group\" aria-label=\"Оценка\"></div>`;\n  const opts = q.querySelector('.opts');\n  for (let v = 0; v <= 4; v++){\n    const o = document.createElement('button'); o.className = 'opt'; o.id = `${idPrefix}-${i}-${v}`;\n    o.setAttribute('aria-pressed', arr[i] === v ? 'true' : 'false');\n    o.innerHTML = `<b>${v}</b><small>${LABELS[v]}</small>`;\n    o.addEventListener('click', () => { arr[i] = v; opts.querySelectorAll('.opt').forEach((x, n) => x.setAttribute('aria-pressed', n === v ? 'true' : 'false')); update(); });\n    opts.appendChild(o);\n  }\n  return q;\n}\nfunction renderStep(){\n  const list = $('qlist'); list.innerHTML = '';\n  if (step === 0){\n    document.documentElement.style.setProperty('--accent', 'var(--plum)');\n    $('partTag').textContent = 'О твоём переезде';\n    $('roleTitle').textContent = 'Где ты сейчас'; $('roleTitle').style.color = 'var(--plum)';\n    $('roleSub').textContent = 'Два коротких вопроса, чтобы разбор был точнее.';\n    list.appendChild(choiceGroup('Сколько ты живёшь в новой стране?', YEARS, 'years'));\n    list.appendChild(choiceGroup('Какая фраза сейчас ближе всего?', STAGES.map(s => s.phrase), 'stage'));\n    list.appendChild(choiceGroup(STAY_Q, STAY_OPTS, 'stay'));\n  } else if (step <= 3){\n    const pair = [(step - 1) * 2, (step - 1) * 2 + 1];\n    document.documentElement.style.setProperty('--accent', `var(${AC[pair[0]]})`);\n    $('partTag').textContent = 'Сферы новой жизни · за последние 4 недели';\n    $('roleTitle').textContent = `${AREAS[pair[0]].name} · ${AREAS[pair[1]].name}`; $('roleTitle').style.color = `var(${AC[pair[0]]})`;\n    $('roleSub').textContent = 'Отмечай, как часто это было на самом деле.';\n    let n = (step - 1) * 10;\n    pair.forEach(a => {\n      const h = document.createElement('div'); h.className = 'qhead'; h.style.color = `var(${AC[a]})`; h.textContent = AREAS[a].name; list.appendChild(h);\n      AREAS[a].items.forEach((t, i) => list.appendChild(scaleItem(t, ++n, ans.areas[a], i, `a${a}`)));\n    });\n  } else if (step === 5) {\n    document.documentElement.style.setProperty('--accent', 'var(--plum)');\n    $('partTag').textContent = 'Твоя цель';\n    $('roleTitle').textContent = 'Куда тебе хочется'; $('roleTitle').style.color = 'var(--plum)';\n    $('roleSub').textContent = 'Представь себя через три–шесть месяцев. Насколько крепкой ты хочешь видеть каждую сферу? 0 — сейчас не важно, 10 — крепкая опора. Если хочется, допиши в одну строку, что бы ты хотела изменить.';\n    AREAS.forEach((_, k) => list.appendChild(kGoalItem(k)));\n  } else {\n    document.documentElement.style.setProperty('--accent', 'var(--plum)');\n    $('partTag').textContent = 'Две культуры · за последние 4 недели';\n    $('roleTitle').textContent = 'Твоя культура и новая'; $('roleTitle').style.color = 'var(--plum)';\n    $('roleSub').textContent = 'Здесь нет правильного баланса. Важно просто увидеть, как это у тебя сейчас.';\n    let n = 30;\n    CULT.forEach((c, k) => {\n      const h = document.createElement('div'); h.className = 'qhead'; h.textContent = c.name; list.appendChild(h);\n      c.items.forEach((t, i) => list.appendChild(scaleItem(t, ++n, ans.cult[k], i, `c${k}`)));\n    });\n  }\n  $('stepLabel').textContent = `Шаг ${step + 1} из 6`;\n  $('next').textContent = step === 5 ? 'Показать разбор' : 'Дальше';\n  update();\n}\nfunction doneCount(){\n  return (ctx.years !== null) + (ctx.stage !== null) + (ctx.stay != null) + goals.filter(g => g !== null).length + ans.areas.flat().filter(v => v !== null).length + ans.cult.flat().filter(v => v !== null).length;\n}\nfunction stepComplete(){\n  if (step === 0) return ctx.years !== null && ctx.stage !== null && ctx.stay != null;\n  if (step === 5) return goals.every(g => g !== null);\n  if (step <= 3) return [(step - 1) * 2, (step - 1) * 2 + 1].every(a => ans.areas[a].every(v => v !== null));\n  return ans.cult.every(c => c.every(v => v !== null));\n}\nfunction kGoalItem(k){\n  const q = document.createElement('div'); q.className = 'q st-goal'; q.style.cssText = `--l:${KL[k]};--f:${KF[k]};--s:${KSOFT[k]}`;\n  q.innerHTML = `<div class=\"st-gh\"><span class=\"st-ico\">${aIcon(k)}</span><b>${AREAS[k].name}</b><span class=\"st-gv\"></span></div>\n    <input type=\"range\" min=\"0\" max=\"10\" step=\"1\" aria-label=\"Насколько крепкой ты хочешь видеть сферу «${AREAS[k].name}»\" value=\"${goals[k] ?? 5}\">\n    <div class=\"st-gscale\"><span>0 · не важно сейчас</span><span>10 · крепкая опора</span></div>\n    <textarea class=\"st-gtext\" rows=\"2\" maxlength=\"160\" placeholder=\"Моя цель здесь (по желанию). Например: ${K_GOAL_HINT[k]}\">${esc(goalText[k] || '')}</textarea>`;\n  const r = q.querySelector('input[type=range]'), v = q.querySelector('.st-gv');\n  const paint = () => { v.textContent = goals[k] === null ? 'отметь' : goals[k] + ' из 10'; q.classList.toggle('set', goals[k] !== null); };\n  r.addEventListener('input', () => { goals[k] = +r.value; paint(); update(); });\n  r.addEventListener('pointerdown', () => { if (goals[k] === null){ goals[k] = +r.value; paint(); update(); } });\n  q.querySelector('.st-gtext').addEventListener('input', e => { goalText[k] = e.target.value; kSave(); });\n  paint(); return q;\n}\nfunction kSave(){ try { localStorage.setItem(K_SAVE, JSON.stringify({ step, ctx, ans, goals, goalText, myName, finished, t: Date.now() })); } catch(e){} }\nfunction kLoad(){ try { const v = JSON.parse(localStorage.getItem(K_SAVE) || 'null'); return v && v.ans ? v : null; } catch(e){ return null; } }\nfunction kRestore(v){ ({ ctx, ans, myName, finished } = v); if (ctx.stay === undefined) ctx.stay = null; goals = v.goals || AREAS.map(() => null); goalText = v.goalText || AREAS.map(() => ''); step = Math.min(v.step || 0, 5); $('nameMe').value = myName || ''; }\nfunction update(){\n  kSave();\n  const d = doneCount();\n  $('countLabel').textContent = `${d} из ${TOTAL}`;\n  $('prog').style.width = (d / TOTAL * 100) + '%';\n  $('next').disabled = !stepComplete();\n}\n$('next').addEventListener('click', () => { if (step < 5){ step++; renderStep(); window.scrollTo(0, 0); } else showResult(); });\n$('back').addEventListener('click', () => {\n  if (step > 0){ step--; renderStep(); window.scrollTo(0, 0); }\n  else { $('quiz').hidden = true; $('intro').hidden = false; }\n});\n\n/* ---------- картинки ---------- */\nfunction aIcon(k){\n  const c = css(AC[k]);\n  const p = [\n    `<path d=\"M4 5h16v10H9l-5 4z\" fill=\"none\" stroke=\"${c}\" stroke-width=\"2.2\" stroke-linejoin=\"round\"/>`,\n    `<path d=\"M3 11.2 12 3.5l9 7.7V21h-6.2v-5.6H9.2V21H3z\" fill=\"${c}\"/>`,\n    `<path d=\"M12 3l2.6 5.6 6 .7-4.5 4.1 1.2 6L12 16.4 6.7 19.4l1.2-6L3.4 9.3l6-.7z\" fill=\"${c}\"/>`,\n    `<circle cx=\"8\" cy=\"9\" r=\"3.4\" fill=\"${c}\"/><circle cx=\"16\" cy=\"9\" r=\"3.4\" fill=\"${c}\"/><path d=\"M2.5 20c.6-3.6 3-5.5 5.5-5.5s4.9 1.9 5.5 5.5M10.5 20c.6-3.6 3-5.5 5.5-5.5s4.9 1.9 5.5 5.5\" fill=\"none\" stroke=\"${c}\" stroke-width=\"2\"/>`,\n    `<path d=\"M12 21s-7.5-4.6-7.5-10.2A4.3 4.3 0 0 1 12 8a4.3 4.3 0 0 1 7.5 2.8C19.5 16.4 12 21 12 21z\" fill=\"${c}\"/>`,\n    `<circle cx=\"12\" cy=\"12\" r=\"8.5\" fill=\"none\" stroke=\"${c}\" stroke-width=\"2.2\"/><circle cx=\"12\" cy=\"12\" r=\"3\" fill=\"${c}\"/>`][k];\n  return `<svg viewBox=\"0 0 24 24\" width=\"24\" height=\"24\" aria-hidden=\"true\">${p}</svg>`;\n}\nconst bar = (v, max, color) => `<div class=\"bar\"><i style=\"width:${v / max * 100}%;background:${color}\"></i></div>`;\n\n/* ---------- разбор ---------- */\nfunction compute(){\n  const sc = ans.areas.map(sum);\n  const own = sum(ans.cult[0]), neu = sum(ans.cult[1]);\n  const key = own >= 10 && neu >= 10 ? 'both' : neu >= 10 ? 'newOnly' : own >= 10 ? 'ownOnly' : 'none';\n  const idx = Math.round(sum(sc) / 120 * 100);\n  const strong = sc.indexOf(Math.max(...sc)), weak = sc.lastIndexOf(Math.min(...sc));\n  return { sc, own, neu, key, idx, strong, weak };\n}\nconst kq = s => `«${s}»`;\nconst kJoin = a => a.length < 2 ? a.join('') : a.slice(0, -1).join(', ') + ' и ' + a[a.length - 1];\nfunction kPattern(r){\n  const L = r.sc.map(lvl), ops = L.map((x, k) => x === 2 ? k : -1).filter(k => k >= 0), quiet = L.map((x, k) => x === 0 ? k : -1).filter(k => k >= 0);\n  const n = k => kq(AREAS[k].name.toLowerCase());\n  if (ops.length === 6) return 'Все шесть сфер новой жизни у тебя звучат уверенно. Это очень зрелая картина адаптации: язык, быт, дело, люди, силы и смысл работают вместе. Сейчас хорошее время думать не о том, как справиться, а о том, чего тебе хочется.';\n  if (quiet.length >= 4) return `Сейчас тихо звучат сразу несколько сфер: ${kJoin(quiet.map(n))}. Если тебе тяжело, это объяснимо: адаптация забирает огромное количество сил, и в такие периоды многое держится на минимуме. Не пытайся подтянуть всё сразу. Одна сфера, укреплённая по-настоящему, станет опорой для остальных.`;\n  if (ops.length && quiet.length) return `У тебя уже есть настоящие опоры — ${kJoin(ops.map(n))}. И есть сферы, которые пока звучат тихо: ${kJoin(quiet.map(n))}. Хорошая новость в том, что сильные сферы можно использовать как трамплин: через то, что уже получается, легче дотянуться до того, что пока не идёт.`;\n  if (!quiet.length) return `Ни одна сфера у тебя не провалена${ops.length ? `, а ${kJoin(ops.map(n))} уже стали опорой` : ''}. Остальные в процессе: где-то уже получается, где-то ещё с напряжением. Это нормальная середина пути, и здесь особенно важна регулярность маленьких шагов.`;\n  return `Тихо пока звучат ${kJoin(quiet.map(n))}, а остальные сферы в процессе. Это частая картина первых лет: силы уходят на то, чтобы держаться, а опоры ещё не выросли. Начни с одной сферы, той, где изменения дадут больше всего облегчения.`;\n}\nfunction kItems(k){ return AREAS[k].items.map((t, i) => ({ k, t, a: ans.areas[k][i] })); }\nfunction kWords(r){\n  const low = kItems(r.weak).sort((a, b) => a.a - b.a).slice(0, 2);\n  const strong = AREAS.flatMap((_, k) => k === r.weak ? [] : kItems(k)).filter(x => x.a === 4).filter((x, j, arr) => arr.findIndex(y => y.k === x.k) === j).slice(0, 3);\n  const q = x => `<div class=\"st-quote\" style=\"--l:${KL[x.k]};--s:${KSOFT[x.k]}\"><p>«${x.t.replace(/\\.$/, '')}»</p><span>твой ответ: ${LABELS[x.a]}</span></div>`;\n  return `<div class=\"blk\"><div class=\"eyebrow\">Твои собственные ответы</div><h2>Что ты сама о себе сказала</h2>\n    <p>Самые тихие места сферы ${kq(AREAS[r.weak].name.toLowerCase())} — в этих фразах. Перечитай их: часто именно здесь прячется первый шаг.</p>\n    <div class=\"st-quotes\">${low.map(q).join('')}</div>\n    ${strong.length ? `<p>А вот что у тебя получается почти всегда. На это можно опираться:</p><div class=\"st-quotes\">${strong.map(q).join('')}</div>` : ''}</div>`;\n}\nfunction kContext(r){\n  const L = [];\n  if (ctx.stage === 1 && ctx.years >= 3) L.push('Трудный период после нескольких лет в стране — это не откат назад, а новая волна. Часто она приходит, когда первые задачи решены, и встаёт вопрос: а дальше что?');\n  if (ctx.stage === 0 && r.sc.filter(x => lvl(x) === 0).length >= 2) L.push('Ты чувствуешь вдохновение, хотя несколько сфер пока звучат тихо. Это прекрасная энергия, и её стоит направить на закладку опор, пока она есть.');\n  if (ctx.stage === 3 && r.sc.some(x => lvl(x) === 0)) L.push(`Ты чувствуешь, что здесь твой дом, и всё же сфера ${kq(AREAS[r.weak].name.toLowerCase())} звучит тихо. Возможно, это не про адаптацию, а про то, чего тебе хочется дальше.`);\n  if (r.key === 'ownOnly' && (ctx.stay === 2 || ctx.stay === 3)) L.push('Ты держишься за свою культуру и пока не решила остаться. Это часто идёт вместе: когда связи «там» сильнее связей «здесь», и решение, и адаптация откладываются. Это не плохо, но стоит видеть эту связь.');\n  if (r.key === 'newOnly' && ctx.stay === 0) L.push('Ты решила остаться и активно входишь в новую культуру. Подумай, что из своей ты хочешь сохранить: корни дают силы, когда становится трудно.');\n  if (r.key === 'none' && ctx.years <= 1) L.push('Сразу после переезда связь и со своей, и с новой культурой часто звучит тихо: сил хватает только на главное. Это пройдёт, особенно если начать с одного маленького ритуала.');\n  return L;\n}\nfunction kStops(r, gaps, G){\n  const S = [];\n  if (r.sc[4] <= 13) S.push(['Мало сил', 'Сфера «ресурс» звучит тихо, а без сил любое движение даётся вдвое тяжелее. Это первое, о чём стоит позаботиться.']);\n  if (r.sc[3] <= 13) S.push(['Мало поддержки', 'Когда рядом мало людей, на которых можно опереться, даже хорошая цель гаснет на полпути.']);\n  if (Math.max(...gaps) <= 10) S.push(['Нет ясной цели', 'То, куда тебе хочется, почти совпадает с тем, что есть. Иногда это усталость, а иногда тихий запрет хотеть. Ясную цель можно найти.']);\n  else if (!goalText.some(t => t && t.trim())) S.push(['Цель пока размыта', 'Ты отметила, насколько хочешь укрепить сферы, но не описала словами, как это будет выглядеть. Когда непонятно, как выглядит «получилось», трудно сделать первый шаг.']);\n  if (ctx.stay === 2 || ctx.stay === 4) S.push(['Горизонт не ясен', 'Пока не ясно, надолго ли ты здесь, трудно вкладываться в долгие цели: язык, дело, друзей.']);\n  if (r.sc[0] <= 13 && G !== 0) S.push(['Язык как барьер', 'Язык открывает двери ко всему остальному. Пока он звучит тихо, многие цели упираются в него.']);\n  return S.slice(0, 3);\n}\nfunction buildBlocks(){\n  const r = compute(); last = r;\n  const PDF = !!window.__PDF;\n  const N = esc(myName);\n  const [sName, sText] = STRATEGY[r.key];\n  const st = STAGES[ctx.stage];\n  const date = new Date().toLocaleDateString(DATE_LOCALE, { day: 'numeric', month: 'long', year: 'numeric' });\n  const cur = r.sc.map(x => Math.round(x / 20 * 100)), goal = goals.map(g => (g ?? 0) * 10);\n  const gaps = cur.map((v, k) => goal[k] - v), G = gaps.indexOf(Math.max(...gaps));\n  const country = window.__leadCountry || ((typeof loadLead === 'function' && loadLead()) || {}).country || '';\n  const sec = AREAS.map((a, k) => ({ label: a.short, fill: KF[k], line: KL[k] }));\n  const tile = (lab, val, col) => `<div class=\"st-tile2\" style=\"--l:${col}\"><span>${lab}</span><b>${val}</b></div>`;\n  const B = [];\n  const kflat = Math.max(...r.sc) - Math.min(...r.sc) < 2;\n  const portrait = `${kflat ? `${N ? N + ', в' : 'В'}се шесть сфер у тебя сейчас звучат примерно одинаково.` : `${N ? N + ', с' : 'С'}ейчас твоя главная опора — ${kq(AREAS[r.strong].name.toLowerCase())}, а тише всего звучит ${kq(AREAS[r.weak].name.toLowerCase())}.`} С двумя культурами ты на позиции «${sName.toLowerCase()}», а по ощущению это ${st.name.toLowerCase()}. ${ctx.stay != null ? ['Ты решила остаться.', 'Ты скорее остаёшься, но иногда сомневаешься.', 'Ты ещё не решила, остаться ли.', 'Ты думаешь вернуться или уехать дальше.', 'Решение остаться зависит не только от тебя.'][ctx.stay] : ''}${gaps[G] > 10 ? ` Больше всего тебе хочется укрепить ${kq(AREAS[G].name.toLowerCase())}.` : ''}`;\n\n  B.push({ html: `<div class=\"blk st-cover k-cover\" style=\"--l:#6E4F3C;--s:#F3EADF\">\n      <div class=\"st-cover-top\"><div><div class=\"eyebrow\">Компас адаптации · разбор</div>${N ? `<div class=\"names\">${N}</div>` : ''}\n        <p class=\"note\">${date} · в стране ${YEARS[ctx.years]}${ctx.stay != null ? ' · ' + K_STAY_SHORT[ctx.stay] : ''}</p></div>\n        <div class=\"st-cover-ico\">${compassSVG().replace('width=\"150\" height=\"150\"', 'width=\"64\" height=\"64\"')}</div></div>\n      <p class=\"st-now\">Твой путь между двумя культурами</p><h1 style=\"color:#6E4F3C\">${sName}</h1>\n      <p class=\"st-portrait\">${portrait}</p>\n      <div class=\"st-tiles2\">${tile('Этап', st.name, '#8E8470')}${tile('Опора', AREAS[r.strong].short, KL[r.strong])}${tile('Сфера роста', AREAS[r.weak].short, KL[r.weak])}${tile('Индекс адаптации', r.idx + '%', '#6E4F3C')}</div></div>` });\n\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Две культуры</div>\n      <div class=\"st-two\"><div style=\"max-width:360px;width:100%;margin:0 auto\">${shoresSVG(r.own, r.neu)}</div>\n      <div class=\"stack\" style=\"gap:10px\"><h2>${sName}</h2><p>${sText}</p>\n      <p class=\"note\">Своя культура: <b>${r.own} из 20</b> · новая культура: <b>${r.neu} из 20</b>. Связь считается сильной от 10 баллов.</p></div></div></div>` });\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Этап адаптации</div><h2>${st.name}</h2>${journeySVG(ctx.stage)}<p>${st.text}</p>\n      ${kContext(r).map(t => `<p class=\"st-ctx\">${t}</p>`).join('')}\n      <p class=\"note\">Этапы описаны по классической модели адаптации к новой культуре (U-кривая). У каждого человека свой темп, и этапы могут повторяться.</p></div>` });\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Шесть сфер</div><h2>Шесть сфер твоей новой жизни</h2>\n      <div class=\"st-two\"><div>${flowerSVG(r.sc)}</div><div class=\"stack\" style=\"gap:10px\"><p>${kPattern(r)}</p>\n      <p class=\"note\">Каждая сфера — от 0 до 20 баллов. Общий индекс адаптации: <b>${r.idx}%</b>. Это не оценка, а точка отсчёта.</p></div></div></div>` });\n\n  const areaCard = k => { const sc = r.sc[k], l = lvl(sc);\n    return `<div class=\"k-area\" style=\"--c:${KL[k]};--cs:${KSOFT[k]}\"><div class=\"role-head\"><div class=\"ico\">${aIcon(k)}</div><h3>${AREAS[k].name}</h3><span class=\"sc\">${sc} / 20</span></div>\n      <span class=\"pill\" style=\"background:${KL[k]};align-self:flex-start\">${LV_NAME[l]}</span><p>${AREAS[k].lv[l]}</p>\n      ${l === 2 ? `<p class=\"note\">${KEEP}</p>` : `<div class=\"recs-t\">Что поможет</div><ul class=\"recs\" style=\"--cs:${KSOFT[k]}\">${AREAS[k].recs.map(x => `<li>${x}</li>`).join('')}</ul>`}</div>`; };\n  [[0, 1], [2, 3], [4, 5]].forEach((pair, i) => B.push({ html: `<div class=\"blk\">${i === 0 ? '<div class=\"eyebrow\">Подробно по сферам</div><h2>Где твои опоры и где пока тихо</h2>' : ''}<div class=\"k-areas\">${pair.map(areaCard).join('')}</div></div>` }));\n  B.push({ html: kWords(r) });\n\n  const low = AREAS[r.weak].items.map((t, i) => [t, ans.areas[r.weak][i]]).sort((a, b) => a[1] - b[1]).slice(0, 2);\n  const ritual = ['Раз в неделю делай что-то впервые в новой стране: место, блюдо, событие.',\n                  'Раз в неделю отдыхай по-настоящему: без дел, без телефона, с тем, что тебя наполняет.',\n                  'Раз в неделю отмечай, что уже получилось. Маленькие победы тоже считаются.',\n                  'Раз в месяц думай о том, чего тебе хочется здесь дальше, и выбирай один шаг.',\n                  'Раз в неделю делай что-то бережное для себя и поговори с тем, кто тебя поддерживает.'][ctx.stage];\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">План на 4 недели</div><h2>Маленькие шаги, которые меняют жизнь</h2>\n    <div class=\"steps\">\n      <div><span class=\"num\">1</span><div><b>Твоя сфера роста: ${AREAS[r.weak].name.toLowerCase()}</b><p>Выбери одно действие и делай его хотя бы два раза в неделю:</p>\n        <ul class=\"clean\" style=\"margin-top:6px\">${low.map(([t]) => `<li>${t.replace(/^Я (сама или сам )?/, '').replace(/^./, c => c.toUpperCase())}</li>`).join('')}</ul></div></div>\n      <div><span class=\"num\">2</span><div><b>Твоя опора: ${AREAS[r.strong].name.toLowerCase()}</b><p>Когда становится трудно, опирайся на эту сферу. Замечай, что в ней у тебя получается, и позволь ей поддерживать остальные.</p></div></div>\n      <div><span class=\"num\">3</span><div><b>Ритуал этапа «${st.name.toLowerCase()}»</b><p>${ritual}</p></div></div>\n      <div><span class=\"num\">4</span><div><b>Через 4 недели</b><p>Пройди тест ещё раз и посмотри, как изменился твой компас.</p></div></div>\n    </div></div>` });\n  { const ctry = country;\n    if (!ctry || ctry === 'Швейцария') {\n      const inCH = ctry === 'Швейцария';\n      B.push({ float: true, html: `<div class=\"blk swiss-guide\"><div class=\"eyebrow\">${inCH ? 'Для жизни в Швейцарии' : 'Если ты живёшь в Швейцарии'}</div><h2>Гайд по Швейцарии — Swiss Guide</h2>\n        <p>${r.weak === 1 ? 'Сейчас больше всего сил забирают быт и система. ' : ''}Это мой бесплатный Telegram-бот на русском. В нём собраны ответы на практические вопросы о жизни в Швейцарии: документы и разрешения, страховки, налоги, школа, жильё, письма из общины и неписаные правила. Чтобы силы оставались на то, что важно именно тебе.</p>\n        <div class=\"invite-links\"><a href=\"https://t.me/swisscompass_bot\" target=\"_blank\" rel=\"noopener\">Открыть бот: @swisscompass_bot</a></div></div>` });\n    } }\n\n  /* цель и колёса */\n  const texts = goalText.map((t, k) => [k, (t || '').trim()]).filter(x => x[1]);\n  let gapTxt = gaps[G] <= 10 ? 'Похоже, сейчас тебе трудно сказать, куда хочется: цели почти совпадают с тем, что есть. Так бывает, когда сил хватает только на сегодня, или когда хотеть кажется опасным. Ясная цель не появляется сама, её можно найти, и это первое, чем мы могли бы заняться вместе.'\n    : `Самое большое расстояние в сфере ${kq(AREAS[G].name.toLowerCase())}: сейчас ${cur[G]}%, а хочется ${goal[G]}%.` + (G === r.weak ? ' И это та же сфера, которая сейчас звучит тише всего: желание и потребность смотрят в одну сторону, это хороший знак.' : ` А тише всего сейчас звучит ${kq(AREAS[r.weak].name.toLowerCase())}. Иногда именно она мешает дотянуться до желанного: стоит проверить, не держит ли она тебя.`);\n  { const big = gaps.map((g, k) => [g, k]).filter(([g]) => g >= 20).sort((a, b) => b[0] - a[0]); if (big.length > 1) gapTxt += ' Заметно укрепить тебе хочется ' + kJoin(big.slice(0, 3).map(([g, k]) => `${kq(AREAS[k].name.toLowerCase())} (с ${cur[k]} до ${goal[k]}%)`)) + '.'; }\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Где ты сейчас и куда хочется</div><h2>Три колеса твоей жизни</h2>\n    <p>Шесть сфер по кругу. Чем длиннее лепесток, тем крепче сфера. Первое колесо — где ты сейчас, второе — куда тебе хочется, третье показывает оба сразу: расстояние между закрашенным лепестком и пунктиром и есть твой путь.</p>\n    <div class=\"st-wheels3\"><figure class=\"both\">${petalWheelSVG(sec, cur, goal)}<figcaption>Вместе: сейчас и хочется</figcaption></figure><figure>${petalWheelSVG(sec, cur)}<figcaption>Где ты сейчас</figcaption></figure><figure>${petalWheelSVG(sec, goal)}<figcaption>Куда хочется</figcaption></figure></div>\n    ${WHEEL_LEGEND}</div>` });\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Твой путь</div><h2>Разница между «сейчас» и «хочется»</h2><p>${gapTxt}</p>\n    ${texts.length ? `<div class=\"st-goals\"><b>Твои слова о цели</b>${texts.map(([k, t]) => `<p style=\"--l:${KL[k]}\"><span>${AREAS[k].name}</span>${esc(t)}</p>`).join('')}</div>` : ''}</div>` });\n  if (ctx.stay != null) B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Остаться или нет</div><h2>${K_STAY[ctx.stay][0]}</h2><p>${K_STAY[ctx.stay][1]}</p></div>` });\n  const stops = kStops(r, gaps, G);\n  if (stops.length) B.push({ html: `<div class=\"blk st-hold\"><div class=\"eyebrow\">Что удерживает</div><h2>Что тебя сейчас останавливает</h2>\n    <div class=\"st-stops\">${stops.map(([h, t]) => `<div><b>${h}</b><p>${t}</p></div>`).join('')}</div>\n    <p>Всё это не приговор. Перемена случается, когда есть силы, ощущение «так больше не хочу», ясность, куда идти, названный барьер и поддержка рядом. Каждое из этих условий можно создать.</p></div>` });\n  B.push({ html: `<div class=\"blk\"><h2>Вопросы для размышления</h2><p class=\"note\">Не торопись с ответами. Можно записать их или просто побыть с ними.</p>\n    <ul class=\"clean\">\n      <li>Когда ты на своём месте, ты как что? На что это похоже?</li>\n      <li>Что тебе уже помогает в новой стране? Что ещё могло бы помочь?</li>\n      <li>Чего тебе хочется для себя в этой стране?</li>\n      <li>Что из прежней жизни ты хочешь сохранить, а что можно бережно отпустить?</li>\n      <li>Кто или что поддерживает тебя здесь?</li>\n      <li>Какой маленький шаг на этой неделе приблизит тебя к ощущению «я дома»?</li>\n    </ul></div>` });\n  B.push({ html: `<div class=\"blk st-together\"><div class=\"eyebrow\">Путь, который можно пройти вместе</div><h2>${N ? N + ', это' : 'Это'} твой путь от одного колеса к другому</h2>\n    <p>Его можно пройти одной. А можно вместе, в партнёрстве. В коучинге я не даю советов и не решаю за тебя. Я работаю на глубине, через эмоциональный интеллект. Мы вместе находим, что держит именно тебя, превращаем «хочу, чтобы было хорошо» в ясную цель, которая по-настоящему твоя, и идём к ней маленькими шагами в твоём темпе, опираясь на сферы, которые у тебя уже крепкие.</p></div>` });\n  B.push({ html: inviteHtml({ name: myName, country: window.__leadCountry || '', interest: surveyAnswers().interest,\n                              focus: { coach: AREAS[r.weak].focus, psy: 'в отношениях стало больше тепла и понимания' } }) });\n  B.push({ float: true, html: channelHtml(window.__leadCountry || country) });\n  B.push({ float: true, html: `<div class=\"blk testinfo\"><div class=\"eyebrow\">Об этом опроснике</div><p>${TEST_INFO.why}</p>${PDF ? '' : abHtml()}</div>` });\n  B.push({ float: true, html: moreTestsHtml(TEST_META.id) });\n  B.push({ html: authorHtml() });\n  B.push({ html: disclaimerHtml() });\n  r.sName = sName;\n  return B;\n}\nfunction showResult(){\n  finished = true; kSave(); kResume();\n  $('report').innerHTML = buildBlocks().map(b => b.html).join('');\n  $('quiz').hidden = true; $('result').hidden = false; window.scrollTo(0, 0);\n}\n\n/* ---------- связь с общей анкетой ---------- */\nconst LEAD_HOOKS = {\n  personName: () => myName,\n  fileBase: () => 'Kompas_adaptatsii',\n  fileNames: () => myName ? [myName] : [],\n  payload: () => {\n    const r = last, scores = {};\n    AREAS.forEach((a, k) => scores[a.name] = r.sc[k]);\n    AREAS.forEach((a, k) => scores['Цель: ' + a.name + ' (0–10)'] = goals[k]);\n    scores['Своя культура'] = r.own; scores['Новая культура'] = r.neu; scores['Индекс адаптации, %'] = r.idx;\n    return { result: r.sName, scores, notes: `в стране: ${YEARS[ctx.years]}; остаться: ${ctx.stay != null ? STAY_OPTS[ctx.stay] : '—'}; цели: ${goalText.map((t, k) => t && t.trim() ? AREAS[k].short + ' — ' + t.trim() : '').filter(Boolean).join(' | ') || '—'}; этап: ${STAGES[ctx.stage].name}; опора: ${AREAS[r.strong].name}; рост: ${AREAS[r.weak].name}` };\n  }\n};\n\n/* значки на плитках сфер на стартовой странице */\ndocument.querySelectorAll('.k-roles .role').forEach((el, k) => {\n  const b = el.querySelector('b'); if (!b) return;\n  const w = document.createElement('div'); w.className = 'ri';\n  w.innerHTML = aIcon(k); b.parentNode.insertBefore(w, b); w.appendChild(b);\n});\n\n/* ---------- точка А → Б и «продолжить» ---------- */\ndocument.getElementById('kAB').innerHTML = abHtml();\nfunction kResume(){\n  const box = $('kResume'), v = kLoad(); if (!box) return;\n  if (!v){ box.hidden = true; box.innerHTML = ''; return; }\n  const when = new Date(v.t).toLocaleDateString(DATE_LOCALE, { day: 'numeric', month: 'long' });\n  box.hidden = false;\n  box.innerHTML = v.finished\n    ? `<div><b>${v.myName ? esc(v.myName) + ', т' : 'Т'}вой разбор «Компаса адаптации» от ${when} сохранён</b><p>Можно открыть его снова или пройти тест заново через несколько недель, чтобы увидеть, как изменился компас.</p></div>\n       <div class=\"st-resume-btns\"><button type=\"button\" class=\"btn\" id=\"kOpen\">Открыть мой разбор</button><button type=\"button\" class=\"btn ghost\" id=\"kNew\">Пройти заново</button></div>`\n    : `<div><b>${v.myName ? esc(v.myName) + ', т' : 'Т'}ы уже начинала «Компас адаптации» ${when}</b><p>Твои ответы сохранились. Можно продолжить с того места, где ты остановилась.</p></div>\n       <div class=\"st-resume-btns\"><button type=\"button\" class=\"btn\" id=\"kGo\">Продолжить</button><button type=\"button\" class=\"btn ghost\" id=\"kNew\">Начать заново</button></div>`;\n  const go = $('kGo'), op = $('kOpen');\n  if (go) go.addEventListener('click', () => { kRestore(kLoad()); resetInvite(); $('intro').hidden = true; $('quiz').hidden = false; renderStep(); window.scrollTo(0, 0); });\n  if (op) op.addEventListener('click', () => { kRestore(kLoad()); resetInvite(); showResult(); });\n  $('kNew').addEventListener('click', () => { try { localStorage.removeItem(K_SAVE); } catch(e){} kResume(); });\n}\nkResume();\ndocument.documentElement.style.setProperty('--pdf-strip', 'linear-gradient(90deg,' + KF.join(',') + ')');\n", "/* =====================================================================\n   Общая анкета перед PDF, отправка в Google Таблицу и сборка PDF.\n   Тест задаёт: TEST_META {id, name}, buildBlocks(), showResult(), LEAD_HOOKS.\n   ===================================================================== */\n/* Страны — коды ISO; названия показываются на языке страницы, в таблицу уходит русское название. */\nconst COUNTRY_TOP = ['CH','DE','AT','FR','IT','ES','NL','BE','GB','PL','CZ','IL','US','CA','UA','RU','BY','KZ'];\nconst COUNTRY_ALL = ['AU','AT','AZ','AL','DZ','AD','AR','AM','AF','BD','BH','BY','BE','BG','BO','BA','BR','GB','HU','VE','VN','GH','DE','HK','GR','GE','DK','DO','EG','IL','IN','ID','JO','IQ','IR','IE','IS','ES','IT','KZ','KH','CA','QA','KE','CY','KG','CN','CO','CR','CU','KW','LV','LB','LT','LI','LU','MU','MY','MV','MT','MA','MX','MD','MC','MN','ME','NP','NG','NL','NZ','NO','AE','OM','PK','PA','PY','PE','PL','PT','RU','RO','SA','MK','RS','SG','SK','SI','US','TJ','TH','TW','TN','TM','TR','UG','UZ','UA','UY','PH','FI','FR','HR','CZ','CL','CH','SE','LK','EC','EE','ZA','KR','JM','JP'];\nconst PAGE_LANG = (typeof LANG !== 'undefined') ? LANG : 'ru';\nconst countryName = (() => { try { const d = new Intl.DisplayNames([PAGE_LANG], { type:'region' }); return c => d.of(c); } catch(e){ return c => c; } })();\nconst countryRu = (() => { try { const d = new Intl.DisplayNames(['ru'], { type:'region' }); return c => d.of(c); } catch(e){ return c => c; } })();\nconst COUNTRIES = COUNTRY_ALL.map(countryRu);\nconst OTHER_COUNTRY = 'Другая страна';\n\nfunction leadFormHtml(){\n  return `<div class=\"blk actions\" style=\"margin-top:18px\">\n    <h3>Получить разбор в PDF</h3>\n    <p>Красивый PDF с разбором без вопросов теста: картинки, описания, рекомендации, план на 4 недели и вопросы для размышления. Оставь контакты, и файл скачается сразу.</p>\n    <form id=\"lead\" class=\"stack\" style=\"gap:12px\" novalidate>\n      <div class=\"row\" style=\"align-items:stretch\">\n        <div class=\"field\"><label for=\"fName\">Имя *</label><input id=\"fName\" maxlength=\"40\" required autocomplete=\"given-name\"></div>\n        <div class=\"field\"><label for=\"fEmail\">E-mail *</label><input id=\"fEmail\" type=\"email\" maxlength=\"80\" required autocomplete=\"email\"></div>\n      </div>\n      <div class=\"field\"><label for=\"fContact\">Telegram или WhatsApp</label><input id=\"fContact\" maxlength=\"60\" placeholder=\"@username или +41 …\"></div>\n      <div class=\"row\" style=\"align-items:stretch\">\n        <div class=\"field\"><label for=\"fCountry\">Страна *</label><select id=\"fCountry\" required><option value=\"\">Выбери страну</option></select></div>\n        <div class=\"field\"><label for=\"fCity\">Город</label><input id=\"fCity\" maxlength=\"40\" autocomplete=\"address-level2\"></div>\n      </div>\n      <label class=\"check\"><input type=\"checkbox\" id=\"fConsent\" required> <span>Я соглашаюсь на обработку моих данных для отправки результатов и связи со мной *</span></label>\n      <label class=\"check\"><input type=\"checkbox\" id=\"fNews\"> <span>Хочу получать полезные материалы об отношениях, адаптации и жизни в эмиграции</span></label>\n      <p class=\"err\" id=\"formErr\" hidden></p>\n      <div class=\"row\">\n        <button class=\"btn\" type=\"submit\" id=\"pdfBtn\">Получить PDF</button>\n        <button class=\"btn ghost\" type=\"button\" id=\"again\">Пройти заново</button>\n      </div>\n      <p class=\"note\">Твои данные видит только Ирина Вознесенская. Они не передаются третьим лицам.</p>\n    </form>\n    <span class=\"status\" id=\"status\" hidden></span>\n  </div>`;\n}\ndocument.querySelectorAll('[data-lead]').forEach(el => el.innerHTML = leadFormHtml());\n(function fillCountries(){\n  const sel = document.getElementById('fCountry'); if (!sel) return;\n  const g1 = document.createElement('optgroup'); g1.label = 'Часто выбирают';\n  COUNTRY_TOP.forEach(c => g1.appendChild(new Option(countryName(c), countryRu(c))));\n  const g2 = document.createElement('optgroup'); g2.label = 'Все страны';\n  COUNTRY_ALL.map(c => [countryName(c), countryRu(c)]).sort((x, y) => x[0].localeCompare(y[0], PAGE_LANG)).forEach(([n, v]) => g2.appendChild(new Option(n, v)));\n  g2.appendChild(new Option('Другая страна', OTHER_COUNTRY));\n  sel.appendChild(g1); sel.appendChild(g2);\n})();\n\nconst el = id => document.getElementById(id);\nfunction setStatus(t){ el('status').textContent = t; el('status').hidden = !t; }\nfunction setErr(t){ el('formErr').textContent = t; el('formErr').hidden = !t; }\nel('again').addEventListener('click', () => { el('result').hidden = true; el('intro').hidden = false; window.scrollTo(0,0); });\n\nconst LS = 'irinaTestsLead';\nfunction loadLead(){ try { return JSON.parse(localStorage.getItem(LS) || 'null'); } catch(e){ return null; } }\nfunction saveLead(v){ try { localStorage.setItem(LS, JSON.stringify(v)); } catch(e){} }\n\nconst _showResult = showResult;\nshowResult = function(){\n  _showResult();\n  const saved = loadLead();\n  el('fName').value = saved?.name || LEAD_HOOKS.personName() || '';\n  if (saved){\n    el('fEmail').value = saved.email || ''; el('fContact').value = saved.contact || '';\n    el('fCountry').value = (COUNTRIES.includes(saved.country) || saved.country === OTHER_COUNTRY) ? saved.country : '';\n    el('fCity').value = saved.city || '';\n  }\n  setErr(''); setStatus('');\n};\n\n// Чёткость PDF: 3 = около 290 точек на дюйм (хорошо для печати). На слабых телефонах — 2.5.\nconst PDF_SCALE = (/iPhone|iPad|Android/i.test(navigator.userAgent) && (navigator.deviceMemory || 4) < 4) ? 2.5 : 3;\nasync function buildPdf(){\n  const stage = el('stage'); stage.innerHTML = '';\n  window.__PDF = true; let blocks; try { blocks = buildBlocks(); } finally { window.__PDF = false; }\n  const pages = [];\n  const newPage = () => {\n    const p = document.createElement('div'); p.className = 'pdf-page';\n    p.innerHTML = `<div class=\"strip\"></div><div class=\"pbody\"></div><div class=\"pfoot\"><span>${footerLine()}</span><span class=\"pn\"></span></div>`;\n    stage.appendChild(p); pages.push(p); return p.querySelector('.pbody');\n  };\n  let body = newPage();\n  const mk = b => { const h = document.createElement('div'); h.innerHTML = b.html; return h.firstElementChild; };\n  const over = () => body.scrollHeight > body.clientHeight + 1;\n  const used = new Set();\n  for (let i = 0; i < blocks.length; i++){\n    const b = blocks[i];\n    if (!b.html || used.has(i)) continue;\n    if (b.newPage && body.children.length) body = newPage();\n    const node = mk(b);\n    body.appendChild(node);\n    if (over() && body.children.length > 1){\n      node.remove();\n      // свободное место внизу страницы заполняем небольшими «плавающими» блоками, которые идут дальше (float: true)\n      for (let j = i + 1; j < blocks.length; j++){\n        if (!blocks[j].float || used.has(j) || !blocks[j].html) continue;\n        const f = mk(blocks[j]); body.appendChild(f);\n        if (over()) f.remove(); else used.add(j);\n      }\n      body = newPage(); body.appendChild(node);\n    }\n    if (body.scrollHeight > body.clientHeight + 1 && body.children.length === 1){   // один блок выше страницы — уменьшаем, чтобы ничего не обрезалось\n      const k = body.clientHeight / node.scrollHeight;\n      node.style.transformOrigin = 'top left'; node.style.transform = `scale(${k})`; node.style.width = (100 / k) + '%';\n    }\n  }\n  pages.forEach((p, i) => p.querySelector('.pn').textContent = `${i+1} / ${pages.length}`);\n  if (document.fonts && document.fonts.ready) await document.fonts.ready;\n  const { jsPDF } = window.jspdf;\n  const pdf = new jsPDF({ unit:'pt', format:'a4', compress:true });\n  const bg = getComputedStyle(document.documentElement).getPropertyValue('--pdf-bg').trim() || '#FFFFFF';\n  for (let i = 0; i < pages.length; i++){\n    const canvas = await html2canvas(pages[i], { scale:PDF_SCALE, backgroundColor:'#FFFFFF', useCORS:true, logging:false });\n    if (i) pdf.addPage();\n    pdf.addImage(canvas.toDataURL('image/jpeg', 0.95), 'JPEG', 0, 0, 595.28, 841.89, undefined, 'FAST');\n    const pr = pages[i].getBoundingClientRect(), k = 595.28 / pr.width;\n    pages[i].querySelectorAll('a[href]').forEach(a => {\n      if (!/^https?:/.test(a.href)) return;\n      const r = a.getBoundingClientRect();\n      pdf.link((r.left - pr.left) * k, (r.top - pr.top) * k, r.width * k, r.height * k, { url: a.href });\n    });\n  }\n  stage.innerHTML = '';\n  return pdf.output('blob');\n}\n\nfunction translit(t){\n  const m = {а:'a',б:'b',в:'v',г:'g',д:'d',е:'e',ё:'e',ж:'zh',з:'z',и:'i',й:'y',к:'k',л:'l',м:'m',н:'n',о:'o',п:'p',р:'r',с:'s',т:'t',у:'u',ф:'f',х:'kh',ц:'ts',ч:'ch',ш:'sh',щ:'sch',ъ:'',ы:'y',ь:'',э:'e',ю:'yu',я:'ya',і:'i',ї:'yi',є:'ye',ґ:'g'};\n  return String(t).toLowerCase().split('').map(c => m[c] ?? c).join('').replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');\n}\nlet downloadsCap = null;\n(async () => { try { if (window.claude && window.claude.use) downloadsCap = await window.claude.use('downloads'); } catch(e){ downloadsCap = null; } })();\nasync function saveBlob(blob, filename){\n  if (downloadsCap){ await downloadsCap.save({ filename, data: blob }); return; }\n  const url = URL.createObjectURL(blob);\n  const a = document.createElement('a');\n  a.href = url; a.download = filename; a.rel = 'noopener'; document.body.appendChild(a); a.click(); setTimeout(() => a.remove(), 1000);\n  setTimeout(() => URL.revokeObjectURL(url), 60000);\n}\n\nasync function sendLead(lead){\n  if (!ENDPOINT) return;\n  const src = new URLSearchParams(location.search);\n  const sv = surveyAnswers();\n  const t = LEAD_HOOKS.payload();\n  const payload = {\n    ...lead,\n    testId: TEST_META.id, testName: TEST_META.name, lang: PAGE_LANG,\n    heard: sv.heard.join(', '), interest: sv.interest.join(', '),\n    result: t.result, scores: t.scores, notes: t.notes || '',\n    source: src.get('utm_source') || src.get('src') || document.referrer || 'прямой заход'\n  };\n  try {\n    await fetch(ENDPOINT, { method:'POST', mode:'no-cors', headers:{ 'Content-Type':'text/plain;charset=utf-8' }, body: JSON.stringify(payload) });\n  } catch(e){ /* PDF всё равно выдаётся */ }\n}\n\nel('lead').addEventListener('submit', async (ev) => {\n  ev.preventDefault(); setErr('');\n  const lead = {\n    name: el('fName').value.trim(), email: el('fEmail').value.trim(), contact: el('fContact').value.trim(),\n    country: el('fCountry').value.trim(), city: el('fCity').value.trim(), marketing: el('fNews').checked\n  };\n  if (!lead.name) return setErr('Напиши, пожалуйста, своё имя.');\n  if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/.test(lead.email)) return setErr('Проверь e-mail: похоже, в нём ошибка.');\n  if (!lead.country) return setErr('Выбери, пожалуйста, страну из списка.');\n  if (!el('fConsent').checked) return setErr('Чтобы получить PDF, нужно согласие на обработку данных.');\n  if (!window.jspdf || !window.html2canvas) return setErr('Не получилось загрузить модуль PDF. Проверь интернет и обнови страницу.');\n  const btn = el('pdfBtn'); btn.disabled = true; setStatus('Готовлю PDF…');\n  try {\n    saveLead(lead);\n    window.__leadCountry = lead.country;\n    await sendLead(lead);\n    const blob = await buildPdf();\n    const fname = [TEST_META.name, ...LEAD_HOOKS.fileNames(), new Date().toLocaleDateString(DATE_LOCALE)].filter(Boolean).join(' — ').replace(/[\\\\/:*?\"<>|]+/g, ' ').replace(/\\s+/g, ' ').trim();\n    await saveBlob(blob, fname + '.pdf');\n    setStatus('Готово! PDF сохранён. Если он не открылся, загляни в папку «Загрузки».');\n  } catch(e){\n    setStatus('');\n    setErr(e && e.code === 'declined' ? 'Сохранение отменено.' : 'Не получилось подготовить PDF. Попробуй ещё раз.');\n  } finally { btn.disabled = false; }\n});\nwindow.__buildPdf = buildPdf;\n"]};
